25	// Ping-pong double-buffering state for chunked TGET transfers
26	struct TgetPingPongState {
27	    bool usePing = true;
28	    bool hasPending = false;
29	    int64_t pendingDstOffset = 0;
30	    int pendingRows = 0;
31	    int pendingCols = 0;
32	};
33	
34	template <typename GlobalDstData, typename GlobalSrcData, typename TileData, typename StrideT>
35	PTO_INTERNAL void TgetPingPongProcessChunk(
36	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& pingTile, TileData& pongTile,
37	    TgetPingPongState& pp, int64_t remoteOff, int64_t localOff, int chunkRows, int chunkCols,
38	    const StrideT& remoteChunkStride, const StrideT& localChunkStride);
39	
40	template <typename GlobalDstData, typename TileData, typename StrideT>
41	PTO_INTERNAL void TgetPingPongFlush(
42	    GlobalDstData& dstGlobalData, TileData& pingTile, TileData& pongTile, TgetPingPongState& pp,
43	    const StrideT& localChunkStride);
