91	// Process one (DIM_3 × DIM_4) slice: row/col sliding window within a single outer-dim group
92	template <typename GlobalDstData, typename GlobalSrcData, typename TileData, bool canSplitTile>
93	PTO_INTERNAL void TgetProcessSlice(
94	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& stagingTileData, int64_t rmtBase,
95	    int64_t locBase, const int (&rmtStep)[5], const int (&locStep)[5], int gShape3, int gShape4, int tileValidRow,
96	    int tileValidCol)
97	{
98	    using T = typename GlobalSrcData::RawDType;
99	    constexpr bool isDynamicRow = (TileData::ValidRow == DYNAMIC);
100	    constexpr bool isDynamicCol = (TileData::ValidCol == DYNAMIC);
101	    using DynShape = Shape<1, 1, 1, DYNAMIC, DYNAMIC>;
102	    using DynStride = Stride<DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC>;
103	    using SrcViewT = GlobalTensor<T, DynShape, DynStride, GlobalSrcData::layout>;
104	    using DstViewT = GlobalTensor<T, DynShape, DynStride, GlobalDstData::layout>;
105	    DynStride remoteChunkStride(rmtStep[0], rmtStep[1], rmtStep[2], rmtStep[3], rmtStep[4]);
106	    DynStride localChunkStride(locStep[0], locStep[1], locStep[2], locStep[3], locStep[4]);
107	
108	    for (int rowIdx = 0; rowIdx < gShape3; rowIdx += tileValidRow) {
109	        int chunkRows = (rowIdx + tileValidRow <= gShape3) ? tileValidRow : (gShape3 - rowIdx);
110	        if constexpr (isDynamicRow)
111	            stagingTileData.RowMaskInternal = chunkRows;
112	        for (int colIdx = 0; colIdx < gShape4; colIdx += tileValidCol) {
113	            int chunkCols = (colIdx + tileValidCol <= gShape4) ? tileValidCol : (gShape4 - colIdx);
114	            if constexpr (isDynamicCol)
115	                stagingTileData.ColMaskInternal = chunkCols;
116	            int64_t remoteOff =
117	                rmtBase + static_cast<int64_t>(rowIdx) * rmtStep[3] + static_cast<int64_t>(colIdx) * rmtStep[4];
118	            int64_t localOff =
119	                locBase + static_cast<int64_t>(rowIdx) * locStep[3] + static_cast<int64_t>(colIdx) * locStep[4];
120	
121	            if constexpr (canSplitTile) {
122	                bool fullTileChunk = (chunkRows == TileData::Rows) && (chunkCols == TileData::Cols);
123	                if (fullTileChunk) {
124	                    TgetIntraPingPongOneChunk<GlobalDstData, GlobalSrcData, TileData>(
125	                        dstGlobalData, srcGlobalData, stagingTileData, remoteOff, localOff, chunkCols,
126	                        remoteChunkStride, localChunkStride, rmtStep[3], locStep[3]);
127	                    continue;
128	                }
129	            }
130	
131	            DynShape chunkShape(1, 1, 1, chunkRows, chunkCols);
132	            SrcViewT srcView(srcGlobalData.data() + remoteOff, chunkShape, remoteChunkStride);
133	            DstViewT dstView(dstGlobalData.data() + localOff, chunkShape, localChunkStride);
134	            TgetTransferOnce<TileData, DstViewT, SrcViewT>(dstView, srcView, stagingTileData);
135	        }
136	    }
137	}
