139	// Iterate over outer dimensions (DIM_0 × DIM_1 × DIM_2) and dispatch each slice
140	template <typename GlobalDstData, typename GlobalSrcData, typename TileData, bool canSplitTile>
141	PTO_INTERNAL void TgetChunkedLoop(
142	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& stagingTileData, const int (&rmtStep)[5],
143	    const int (&locStep)[5], const int (&gShape)[5], int tileValidRow, int tileValidCol)
144	{
145	    for (int i0 = 0; i0 < gShape[0]; ++i0) {
146	        for (int i1 = 0; i1 < gShape[1]; ++i1) {
147	            for (int i2 = 0; i2 < gShape[2]; ++i2) {
148	                int64_t rmtBase = static_cast<int64_t>(i0) * rmtStep[0] + static_cast<int64_t>(i1) * rmtStep[1] +
149	                                  static_cast<int64_t>(i2) * rmtStep[2];
150	                int64_t locBase = static_cast<int64_t>(i0) * locStep[0] + static_cast<int64_t>(i1) * locStep[1] +
151	                                  static_cast<int64_t>(i2) * locStep[2];
152	                TgetProcessSlice<GlobalDstData, GlobalSrcData, TileData, canSplitTile>(
153	                    dstGlobalData, srcGlobalData, stagingTileData, rmtBase, locBase, rmtStep, locStep, gShape[3],
154	                    gShape[4], tileValidRow, tileValidCol);
155	            }
156	        }
157	    }
158	}
