188	// ============================================================================
189	// TgetChunkedDispatch: Validate chunked constraints and dispatch to the
190	// appropriate chunked transfer path (with or without intra-tile ping-pong).
191	// ============================================================================
192	
193	template <typename GlobalDstData, typename GlobalSrcData, typename TileData>
194	PTO_INTERNAL void TgetChunkedDispatch(
195	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& stagingTileData, const int (&remoteDims)[5],
196	    int singleTileRows, int singleTileCols)
197	{
198	    constexpr bool isDynamicRow = (TileData::ValidRow == DYNAMIC);
199	    constexpr bool isDynamicCol = (TileData::ValidCol == DYNAMIC);
200	
201	    if constexpr (!isDynamicRow) {
202	        PTO_ASSERT(
203	            remoteDims[3] % singleTileRows == 0,
204	            "TGET chunked: shape3 must be divisible by tile ValidRow when ValidRow is static. "
205	            "Use a Tile with DYNAMIC ValidRow for partial row chunk support.");
206	    }
207	    if constexpr (!isDynamicCol) {
208	        PTO_ASSERT(
209	            remoteDims[4] % singleTileCols == 0,
210	            "TGET chunked: shape4 must be divisible by tile ValidCol when ValidCol is static. "
211	            "Use a Tile with DYNAMIC ValidCol for partial column chunk support.");
212	    }
213	
214	    constexpr bool canUseIntraTilePingPong = (TileData::Loc == TileType::Vec) &&
215	                                             (TileData::BFractal == BLayout::RowMajor) &&
216	                                             (TileData::SFractal == SLayout::NoneBox) && (TileData::Rows % 2 == 0);
217	    if constexpr (canUseIntraTilePingPong) {
218	        const int64_t outerChunkGroups = static_cast<int64_t>(remoteDims[0]) * remoteDims[1] * remoteDims[2];
219	        const int64_t rowChunkCount = (static_cast<int64_t>(remoteDims[3]) + singleTileRows - 1) / singleTileRows;
220	        const int64_t colChunkCount = (static_cast<int64_t>(remoteDims[4]) + singleTileCols - 1) / singleTileCols;
221	        const int64_t totalChunkCount = outerChunkGroups * rowChunkCount * colChunkCount;
222	
223	        if (singleTileRows == TileData::Rows && singleTileCols == TileData::Cols && singleTileRows >= 2 &&
224	            totalChunkCount >= 8) {
225	            TgetChunkedSingle<GlobalDstData, GlobalSrcData, TileData, true>(
226	                dstGlobalData, srcGlobalData, stagingTileData, remoteDims[0], remoteDims[1], remoteDims[2],
227	                remoteDims[3], remoteDims[4], singleTileRows, singleTileCols);
228	            return;
229	        }
230	    }
231	
232	    TgetChunkedSingle<GlobalDstData, GlobalSrcData, TileData, false>(
233	        dstGlobalData, srcGlobalData, stagingTileData, remoteDims[0], remoteDims[1], remoteDims[2], remoteDims[3],
234	        remoteDims[4], singleTileRows, singleTileCols);
235	}
