237	// ============================================================================
238	// TGET_IMPL: Remote read operation implementation
239	//
240	// Data flow: srcGlobalData (remote GM) → stagingTileData (UB) → dstGlobalData (local GM)
241	//
242	// Chunked transfer follows the same 2D sliding strategy as TPUT_IMPL
243	// (see TPut.hpp): outer dims iterated explicitly, DIM_3/DIM_4 split into
244	// tile-sized chunks. Static ValidRow/ValidCol require divisibility;
245	// use DYNAMIC for partial chunk support.
246	// ============================================================================
247	
248	template <typename GlobalDstData, typename GlobalSrcData, typename TileData>
249	PTO_INTERNAL void TGET_IMPL(GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& stagingTileData)
250	{
251	    using T = typename GlobalSrcData::RawDType;
252	
253	    static_assert(std::is_same_v<typename GlobalDstData::RawDType, T>, "TGET: src/dst element type mismatch");
254	    static_assert(
255	        std::is_same_v<T, typename TileData::DType>, "TGET: TileData element type must match GlobalData element type");
256	    constexpr bool layoutMatched = (GlobalSrcData::layout == GlobalDstData::layout);
257	    static_assert(layoutMatched, "TGET: src/dst layout mismatch");
258	
259	    const int remoteDims[5] = {
260	        static_cast<int>(srcGlobalData.GetShape(GlobalTensorDim::DIM_0)),
261	        static_cast<int>(srcGlobalData.GetShape(GlobalTensorDim::DIM_1)),
262	        static_cast<int>(srcGlobalData.GetShape(GlobalTensorDim::DIM_2)),
263	        static_cast<int>(srcGlobalData.GetShape(GlobalTensorDim::DIM_3)),
264	        static_cast<int>(srcGlobalData.GetShape(GlobalTensorDim::DIM_4))};
265	
266	    const int64_t totalRemoteRows = static_cast<int64_t>(remoteDims[0]) * remoteDims[1] * remoteDims[2] * remoteDims[3];
267	    const int singleTileRows = stagingTileData.GetValidRow();
268	    const int singleTileCols = stagingTileData.GetValidCol();
269	
270	    PTO_ASSERT(singleTileRows > 0, "TGET: tileValidRow must be greater than 0");
271	    PTO_ASSERT(singleTileCols > 0, "TGET: tileValidCol must be greater than 0");
272	
273	    if (totalRemoteRows == 0 || remoteDims[4] == 0) {
274	        return;
275	    }
276	
277	    if (totalRemoteRows <= singleTileRows && remoteDims[4] <= singleTileCols) {
278	        TgetTransferOnce<TileData, GlobalDstData, GlobalSrcData>(dstGlobalData, srcGlobalData, stagingTileData);
279	        return;
280	    }
281	
282	    TgetChunkedDispatch<GlobalDstData, GlobalSrcData, TileData>(
283	        dstGlobalData, srcGlobalData, stagingTileData, remoteDims, singleTileRows, singleTileCols);
284	}
285	
286	// Process one chunk in the ping-pong pipeline: overlap TSTORE of previous chunk with TLOAD of current chunk
287	template <typename GlobalDstData, typename GlobalSrcData, typename TileData, typename StrideT>
288	PTO_INTERNAL void TgetPingPongProcessChunk(
289	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& pingTile, TileData& pongTile,
290	    TgetPingPongState& pp, int64_t remoteOff, int64_t localOff, int chunkRows, int chunkCols,
291	    const StrideT& remoteChunkStride, const StrideT& localChunkStride)
292	{
293	    using DType = typename GlobalSrcData::RawDType;
294	    constexpr bool isDynamicRow = (TileData::ValidRow == DYNAMIC);
295	    constexpr bool isDynamicCol = (TileData::ValidCol == DYNAMIC);
296	    using DynShape = Shape<1, 1, 1, DYNAMIC, DYNAMIC>;
297	    using SrcViewT = GlobalTensor<DType, DynShape, StrideT, GlobalSrcData::layout>;
298	    using DstViewT = GlobalTensor<DType, DynShape, StrideT, GlobalDstData::layout>;
299	
300	    TileData& loadTile = pp.usePing ? pingTile : pongTile;
301	    event_t curEvent = pp.usePing ? EVENT_ID0 : EVENT_ID1;
302	    if constexpr (isDynamicRow)
303	        loadTile.RowMaskInternal = chunkRows;
304	    if constexpr (isDynamicCol)
305	        loadTile.ColMaskInternal = chunkCols;
306	
307	    DynShape chunkShape(1, 1, 1, chunkRows, chunkCols);
308	    SrcViewT srcView(srcGlobalData.data() + remoteOff, chunkShape, remoteChunkStride);
309	
310	    if (pp.hasPending) {
311	        TileData& storeTile = pp.usePing ? pongTile : pingTile;
312	        event_t prevEvent = pp.usePing ? EVENT_ID1 : EVENT_ID0;
313	        wait_flag(PIPE_MTE2, PIPE_MTE3, prevEvent);
314	        pipe_barrier(PIPE_ALL);
315	        DynShape pendShape(1, 1, 1, pp.pendingRows, pp.pendingCols);
316	        DstViewT pendView(dstGlobalData.data() + pp.pendingDstOffset, pendShape, localChunkStride);
317	        TSTORE(pendView, storeTile);
318	        TLOAD(loadTile, srcView);
319	        set_flag(PIPE_MTE3, PIPE_MTE2, prevEvent);
320	        set_flag(PIPE_MTE2, PIPE_MTE3, curEvent);
321	        wait_flag(PIPE_MTE3, PIPE_MTE2, prevEvent);
322	    } else {
323	        TLOAD(loadTile, srcView);
324	        set_flag(PIPE_MTE2, PIPE_MTE3, curEvent);
325	    }
326	
327	    pp.pendingDstOffset = localOff;
328	    pp.pendingRows = chunkRows;
329	    pp.pendingCols = chunkCols;
330	    pp.hasPending = true;
331	    pp.usePing = !pp.usePing;
332	}
333	
334	// Flush the last pending TSTORE in the ping-pong pipeline
335	template <typename GlobalDstData, typename TileData, typename StrideT>
336	PTO_INTERNAL void TgetPingPongFlush(
337	    GlobalDstData& dstGlobalData, TileData& pingTile, TileData& pongTile, TgetPingPongState& pp,
338	    const StrideT& localChunkStride)
339	{
340	    if (!pp.hasPending)
341	        return;
342	
343	    using DType = typename GlobalDstData::RawDType;
344	    using ChunkShape = Shape<1, 1, 1, DYNAMIC, DYNAMIC>;
345	    using DstView = GlobalTensor<DType, ChunkShape, StrideT, GlobalDstData::layout>;
346	
347	    TileData& finalTile = pp.usePing ? pongTile : pingTile;
348	    event_t finalEvent = pp.usePing ? EVENT_ID1 : EVENT_ID0;
349	    wait_flag(PIPE_MTE2, PIPE_MTE3, finalEvent);
350	    pipe_barrier(PIPE_ALL);
351	    ChunkShape finalShape(1, 1, 1, pp.pendingRows, pp.pendingCols);
352	    DstView finalView(dstGlobalData.data() + pp.pendingDstOffset, finalShape, localChunkStride);
353	    TSTORE(finalView, finalTile);
354	    set_flag(PIPE_MTE3, PIPE_MTE2, finalEvent);
355	    wait_flag(PIPE_MTE3, PIPE_MTE2, finalEvent);
356	}
