358	// 2D sliding chunked transfer with ping-pong double buffering
359	template <typename GlobalDstData, typename GlobalSrcData, typename TileData>
360	PTO_INTERNAL void TgetChunkedPingPong(
361	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& pingTile, TileData& pongTile, int gShape0,
362	    int gShape1, int gShape2, int gShape3, int gShape4, int tileValidRow, int tileValidCol)
363	{
364	    const int remoteStep[5] = {
365	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_0)),
366	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_1)),
367	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_2)),
368	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_3)),
369	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_4))};
370	    const int localStep[5] = {
371	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_0)),
372	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_1)),
373	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_2)),
374	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_3)),
375	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_4))};
376	
377	    using DynStride = Stride<DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC>;
378	    DynStride remoteChunkStride(remoteStep[0], remoteStep[1], remoteStep[2], remoteStep[3], remoteStep[4]);
379	    DynStride localChunkStride(localStep[0], localStep[1], localStep[2], localStep[3], localStep[4]);
380	
381	    TgetPingPongState pp;
382	
383	    for (int i0 = 0; i0 < gShape0; ++i0) {
384	        for (int i1 = 0; i1 < gShape1; ++i1) {
385	            for (int i2 = 0; i2 < gShape2; ++i2) {
386	                int64_t remoteBase = static_cast<int64_t>(i0) * remoteStep[0] +
387	                                     static_cast<int64_t>(i1) * remoteStep[1] +
388	                                     static_cast<int64_t>(i2) * remoteStep[2];
389	                int64_t localBase = static_cast<int64_t>(i0) * localStep[0] + static_cast<int64_t>(i1) * localStep[1] +
390	                                    static_cast<int64_t>(i2) * localStep[2];
391	                for (int rowIdx = 0; rowIdx < gShape3; rowIdx += tileValidRow) {
392	                    int chunkRows = (rowIdx + tileValidRow <= gShape3) ? tileValidRow : (gShape3 - rowIdx);
393	                    for (int colIdx = 0; colIdx < gShape4; colIdx += tileValidCol) {
394	                        int chunkCols = (colIdx + tileValidCol <= gShape4) ? tileValidCol : (gShape4 - colIdx);
395	                        int64_t remoteOff = remoteBase + static_cast<int64_t>(rowIdx) * remoteStep[3] +
396	                                            static_cast<int64_t>(colIdx) * remoteStep[4];
397	                        int64_t localOff = localBase + static_cast<int64_t>(rowIdx) * localStep[3] +
398	                                           static_cast<int64_t>(colIdx) * localStep[4];
399	                        TgetPingPongProcessChunk<GlobalDstData, GlobalSrcData, TileData>(
400	                            dstGlobalData, srcGlobalData, pingTile, pongTile, pp, remoteOff, localOff, chunkRows,
401	                            chunkCols, remoteChunkStride, localChunkStride);
402	                    }
403	                }
404	            }
405	        }
406	    }
407	
408	    TgetPingPongFlush<GlobalDstData, TileData>(dstGlobalData, pingTile, pongTile, pp, localChunkStride);
409	}
410	
411	// ============================================================================
412	// TGET_IMPL (ping-pong): Remote read with double buffering
413	// ============================================================================
414	
415	template <typename GlobalDstData, typename GlobalSrcData, typename TileData>
416	PTO_INTERNAL void TGET_IMPL(
417	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& pingTile, TileData& pongTile)
418	{
419	    using T = typename GlobalSrcData::RawDType;
420	
421	    static_assert(std::is_same_v<T, typename GlobalDstData::RawDType>, "TGET: src/dst element type mismatch");
422	    static_assert(GlobalSrcData::layout == GlobalDstData::layout, "TGET: src/dst layout mismatch");
423	    static_assert(
424	        std::is_same_v<T, typename TileData::DType>, "TGET: TileData element type must match GlobalData element type");
425	
426	    const int remoteDim0 = srcGlobalData.GetShape(GlobalTensorDim::DIM_0);
427	    const int remoteDim1 = srcGlobalData.GetShape(GlobalTensorDim::DIM_1);
428	    const int remoteDim2 = srcGlobalData.GetShape(GlobalTensorDim::DIM_2);
429	    const int remoteDim3 = srcGlobalData.GetShape(GlobalTensorDim::DIM_3);
430	    const int remoteDim4 = srcGlobalData.GetShape(GlobalTensorDim::DIM_4);
431	
432	    const int64_t totalRemoteRows = static_cast<int64_t>(remoteDim0) * remoteDim1 * remoteDim2 * remoteDim3;
433	    const int pingRows = pingTile.GetValidRow();
434	    const int pingCols = pingTile.GetValidCol();
435	
436	    PTO_ASSERT(pingRows > 0, "TGET: tileValidRow must be greater than 0");
437	    PTO_ASSERT(pingCols > 0, "TGET: tileValidCol must be greater than 0");
438	
439	    if (totalRemoteRows == 0 || remoteDim4 == 0) {
440	        return;
441	    }
442	
443	    if (totalRemoteRows <= pingRows && remoteDim4 <= pingCols) {
444	        TgetTransferOnce<TileData, GlobalDstData, GlobalSrcData>(dstGlobalData, srcGlobalData, pingTile);
445	        return;
446	    }
447	
448	    constexpr bool isDynamicRow = (TileData::ValidRow == DYNAMIC);
449	    constexpr bool isDynamicCol = (TileData::ValidCol == DYNAMIC);
450	
451	    if constexpr (!isDynamicRow) {
452	        PTO_ASSERT(
453	            remoteDim3 % pingRows == 0,
454	            "TGET chunked: shape3 must be divisible by tile ValidRow when ValidRow is static. "
455	            "Use a Tile with DYNAMIC ValidRow for partial row chunk support.");
456	    }
457	    if constexpr (!isDynamicCol) {
458	        PTO_ASSERT(
459	            remoteDim4 % pingCols == 0,
460	            "TGET chunked: shape4 must be divisible by tile ValidCol when ValidCol is static. "
461	            "Use a Tile with DYNAMIC ValidCol for partial column chunk support.");
462	    }
463	
464	    TgetChunkedPingPong<GlobalDstData, GlobalSrcData, TileData>(
465	        dstGlobalData, srcGlobalData, pingTile, pongTile, remoteDim0, remoteDim1, remoteDim2, remoteDim3, remoteDim4,
466	        pingRows, pingCols);
467	}
468	
469	} // namespace comm
470	} // namespace pto
471	
472	#endif // PTO_COMM_TGET_HPP
