70	    // Wait until all signals satisfy the condition (full 5-D traversal)
71	    bool allSatisfied = false;
72	    uint32_t spin = 0;
73	    constexpr uint32_t kFenceInterval = 64;
74	    constexpr uint32_t kMaxSpinCount = 100000000; // Deadlock detection threshold
75	    while (!allSatisfied) {
