25	// Ping-pong double-buffering state for chunked TPUT transfers
26	struct TputPingPongState {
27	    bool usePing = true;
28	    bool hasPending = false;
29	    int64_t pendingDstOffset = 0;
30	    int pendingRows = 0;
31	    int pendingCols = 0;
32	};
33	
34	template <typename GlobalDstData, typename GlobalSrcData, typename TileData, AtomicType atomicType, typename StrideT>
35	PTO_INTERNAL void TputPingPongProcessChunk(
36	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& pingTile, TileData& pongTile,
37	    TputPingPongState& pp, int64_t srcOff, int64_t dstOff, int curRows, int curCols, const StrideT& srcChunkStride,
38	    const StrideT& dstChunkStride);
39	
40	template <typename GlobalDstData, typename TileData, AtomicType atomicType, typename StrideT>
41	PTO_INTERNAL void TputPingPongFlush(
42	    GlobalDstData& dstGlobalData, TileData& pingTile, TileData& pongTile, TputPingPongState& pp,
43	    const StrideT& dstChunkStride);
44	
45	// Single synchronous transfer: TLOAD from src → sync → TSTORE to dst → sync
46	template <typename TileData, typename DstGT, typename SrcGT, AtomicType atomicType>
47	PTO_INTERNAL void TputTransferOnce(DstGT& dst, SrcGT& src, TileData& tile)
48	{
49	    TLOAD(tile, src);
50	    set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
51	    wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
52	    pipe_barrier(PIPE_ALL);
53	    TSTORE_IMPL<TileData, DstGT, atomicType>(dst, tile);
54	    set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
55	    wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
56	}
57	
58	// Process one full-tile chunk using intra-tile ping-pong (split tile into halves)
59	template <typename GlobalDstData, typename GlobalSrcData, typename TileData, AtomicType atomicType, typename StrideT>
60	PTO_INTERNAL void TputIntraPingPongOneChunk(
61	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& stagingTileData, int64_t srcOff,
62	    int64_t dstOff, int curCols, const StrideT& srcChunkStride, const StrideT& dstChunkStride, int srcRowStride,
63	    int dstRowStride)
64	{
65	    constexpr int kHalfRows = TileData::Rows / 2;
66	    using HalfTileData = Tile<
67	        TileData::Loc, typename TileData::DType, kHalfRows, TileData::Cols, TileData::BFractal, DYNAMIC, DYNAMIC,
68	        TileData::SFractal, TileData::SFractalSize, TileData::PadVal, TileData::Compact>;
69	
70	    HalfTileData pingHalf(kHalfRows, curCols);
71	    HalfTileData pongHalf(kHalfRows, curCols);
72	    const auto baseAddr = reinterpret_cast<std::uintptr_t>(stagingTileData.data());
73	    const auto halfAddr = reinterpret_cast<std::uintptr_t>(stagingTileData.data() + kHalfRows * TileData::Cols);
74	    TASSIGN_IMPL(pingHalf, baseAddr);
75	    TASSIGN_IMPL(pongHalf, halfAddr);
76	    pingHalf.SetKAligned(stagingTileData.GetKAligned());
77	    pongHalf.SetKAligned(stagingTileData.GetKAligned());
78	
79	    TputPingPongState pp;
80	    TputPingPongProcessChunk<GlobalDstData, GlobalSrcData, HalfTileData, atomicType>(
81	        dstGlobalData, srcGlobalData, pingHalf, pongHalf, pp, srcOff, dstOff, kHalfRows, curCols, srcChunkStride,
82	        dstChunkStride);
83	    TputPingPongProcessChunk<GlobalDstData, GlobalSrcData, HalfTileData, atomicType>(
84	        dstGlobalData, srcGlobalData, pingHalf, pongHalf, pp, srcOff + static_cast<int64_t>(kHalfRows) * srcRowStride,
85	        dstOff + static_cast<int64_t>(kHalfRows) * dstRowStride, kHalfRows, curCols, srcChunkStride, dstChunkStride);
86	    TputPingPongFlush<GlobalDstData, HalfTileData, atomicType>(dstGlobalData, pingHalf, pongHalf, pp, dstChunkStride);
87	}
88	
89	// Process one (DIM_3 × DIM_4) slice: row/col sliding window within a single outer-dim group
90	template <typename GlobalDstData, typename GlobalSrcData, typename TileData, AtomicType atomicType, bool canSplitTile>
91	PTO_INTERNAL void TputProcessSlice(
92	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& stagingTileData, int64_t srcBase,
93	    int64_t dstBase, const int (&srcStride)[5], const int (&dstStride)[5], int gShape3, int gShape4, int tileValidRow,
94	    int tileValidCol)
95	{
96	    using T = typename GlobalSrcData::RawDType;
97	    constexpr bool isDynamicRow = (TileData::ValidRow == DYNAMIC);
98	    constexpr bool isDynamicCol = (TileData::ValidCol == DYNAMIC);
99	    using DynShape = Shape<1, 1, 1, DYNAMIC, DYNAMIC>;
100	    using DynStride = Stride<DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC>;
101	    using SrcViewT = GlobalTensor<T, DynShape, DynStride, GlobalSrcData::layout>;
102	    using DstViewT = GlobalTensor<T, DynShape, DynStride, GlobalDstData::layout>;
103	    DynStride srcChunkStride(srcStride[0], srcStride[1], srcStride[2], srcStride[3], srcStride[4]);
104	    DynStride dstChunkStride(dstStride[0], dstStride[1], dstStride[2], dstStride[3], dstStride[4]);
105	
106	    for (int rowOff = 0; rowOff < gShape3; rowOff += tileValidRow) {
107	        int curRows = (rowOff + tileValidRow <= gShape3) ? tileValidRow : (gShape3 - rowOff);
108	        if constexpr (isDynamicRow)
109	            stagingTileData.RowMaskInternal = curRows;
110	        for (int colOff = 0; colOff < gShape4; colOff += tileValidCol) {
111	            int curCols = (colOff + tileValidCol <= gShape4) ? tileValidCol : (gShape4 - colOff);
112	            if constexpr (isDynamicCol)
113	                stagingTileData.ColMaskInternal = curCols;
114	            int64_t srcOff =
115	                srcBase + static_cast<int64_t>(rowOff) * srcStride[3] + static_cast<int64_t>(colOff) * srcStride[4];
116	            int64_t dstOff =
117	                dstBase + static_cast<int64_t>(rowOff) * dstStride[3] + static_cast<int64_t>(colOff) * dstStride[4];
118	
119	            if constexpr (canSplitTile) {
120	                bool fullTileChunk = (curRows == TileData::Rows) && (curCols == TileData::Cols);
121	                if (fullTileChunk) {
122	                    TputIntraPingPongOneChunk<GlobalDstData, GlobalSrcData, TileData, atomicType>(
123	                        dstGlobalData, srcGlobalData, stagingTileData, srcOff, dstOff, curCols, srcChunkStride,
124	                        dstChunkStride, srcStride[3], dstStride[3]);
125	                    continue;
126	                }
127	            }
128	
129	            DynShape chunkShape(1, 1, 1, curRows, curCols);
130	            SrcViewT srcView(srcGlobalData.data() + srcOff, chunkShape, srcChunkStride);
131	            DstViewT dstView(dstGlobalData.data() + dstOff, chunkShape, dstChunkStride);
132	            TputTransferOnce<TileData, DstViewT, SrcViewT, atomicType>(dstView, srcView, stagingTileData);
133	        }
134	    }
135	}
136	
137	// Iterate over outer dimensions (DIM_0 × DIM_1 × DIM_2) and dispatch each slice
138	template <typename GlobalDstData, typename GlobalSrcData, typename TileData, AtomicType atomicType, bool canSplitTile>
139	PTO_INTERNAL void TputChunkedLoop(
140	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& stagingTileData, const int (&srcStride)[5],
141	    const int (&dstStride)[5], const int (&gShape)[5], int tileValidRow, int tileValidCol)
142	{
143	    for (int i0 = 0; i0 < gShape[0]; ++i0) {
144	        for (int i1 = 0; i1 < gShape[1]; ++i1) {
145	            for (int i2 = 0; i2 < gShape[2]; ++i2) {
146	                int64_t srcBase = static_cast<int64_t>(i0) * srcStride[0] + static_cast<int64_t>(i1) * srcStride[1] +
147	                                  static_cast<int64_t>(i2) * srcStride[2];
148	                int64_t dstBase = static_cast<int64_t>(i0) * dstStride[0] + static_cast<int64_t>(i1) * dstStride[1] +
149	                                  static_cast<int64_t>(i2) * dstStride[2];
150	                TputProcessSlice<GlobalDstData, GlobalSrcData, TileData, atomicType, canSplitTile>(
151	                    dstGlobalData, srcGlobalData, stagingTileData, srcBase, dstBase, srcStride, dstStride, gShape[3],
152	                    gShape[4], tileValidRow, tileValidCol);
153	            }
154	        }
155	    }
156	}
157	
158	// 2D sliding chunked transfer with single buffer, optionally using intra-tile ping-pong
159	template <
160	    typename GlobalDstData, typename GlobalSrcData, typename TileData, AtomicType atomicType,
161	    bool enableIntraPingPong = false>
162	PTO_INTERNAL void TputChunkedSingle(
163	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& stagingTileData, int gShape0, int gShape1,
164	    int gShape2, int gShape3, int gShape4, int tileValidRow, int tileValidCol)
165	{
166	    constexpr bool canSplitTile = enableIntraPingPong && (TileData::Loc == TileType::Vec) &&
167	                                  (TileData::BFractal == BLayout::RowMajor) &&
168	                                  (TileData::SFractal == SLayout::NoneBox) && (TileData::Rows % 2 == 0);
169	
170	    const int srcStride[5] = {
171	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_0)),
172	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_1)),
173	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_2)),
174	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_3)),
175	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_4))};
176	    const int dstStride[5] = {
177	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_0)),
178	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_1)),
179	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_2)),
180	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_3)),
181	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_4))};
182	    const int gShape[5] = {gShape0, gShape1, gShape2, gShape3, gShape4};
183	
184	    TputChunkedLoop<GlobalDstData, GlobalSrcData, TileData, atomicType, canSplitTile>(
185	        dstGlobalData, srcGlobalData, stagingTileData, srcStride, dstStride, gShape, tileValidRow, tileValidCol);
186	}
187	
188	// ============================================================================
189	// TputChunkedDispatch: Validate chunked constraints and dispatch to the
190	// appropriate chunked transfer path (with or without intra-tile ping-pong).
191	// ============================================================================
192	
193	template <
194	    typename GlobalDstData, typename GlobalSrcData, typename TileData, AtomicType atomicType = AtomicType::AtomicNone>
195	PTO_INTERNAL void TputChunkedDispatch(
196	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& stagingTileData, const int (&logicalDims)[5],
197	    int ubChunkRows, int ubChunkCols)
198	{
199	    constexpr bool isDynamicRow = (TileData::ValidRow == DYNAMIC);
200	    constexpr bool isDynamicCol = (TileData::ValidCol == DYNAMIC);
201	
202	    if constexpr (!isDynamicRow) {
203	        PTO_ASSERT(
204	            logicalDims[3] % ubChunkRows == 0,
205	            "TPUT chunked: shape3 must be divisible by tile ValidRow when ValidRow is static. "
206	            "Use a Tile with DYNAMIC ValidRow for partial row chunk support.");
207	    }
208	    if constexpr (!isDynamicCol) {
209	        PTO_ASSERT(
210	            logicalDims[4] % ubChunkCols == 0,
211	            "TPUT chunked: shape4 must be divisible by tile ValidCol when ValidCol is static. "
212	            "Use a Tile with DYNAMIC ValidCol for partial column chunk support.");
213	    }
214	
215	    constexpr bool canUseIntraTilePingPong = (TileData::Loc == TileType::Vec) &&
216	                                             (TileData::BFractal == BLayout::RowMajor) &&
217	                                             (TileData::SFractal == SLayout::NoneBox) && (TileData::Rows % 2 == 0);
218	    if constexpr (canUseIntraTilePingPong) {
219	        const int64_t outerChunkGroups = static_cast<int64_t>(logicalDims[0]) * logicalDims[1] * logicalDims[2];
220	        const int64_t rowChunkCount = (static_cast<int64_t>(logicalDims[3]) + ubChunkRows - 1) / ubChunkRows;
221	        const int64_t colChunkCount = (static_cast<int64_t>(logicalDims[4]) + ubChunkCols - 1) / ubChunkCols;
222	        const int64_t totalChunkCount = outerChunkGroups * rowChunkCount * colChunkCount;
223	
224	        if (ubChunkRows == TileData::Rows && ubChunkCols == TileData::Cols && ubChunkRows >= 2 &&
225	            totalChunkCount >= 8 && totalChunkCount <= 16) {
226	            TputChunkedSingle<GlobalDstData, GlobalSrcData, TileData, atomicType, true>(
227	                dstGlobalData, srcGlobalData, stagingTileData, logicalDims[0], logicalDims[1], logicalDims[2],
228	                logicalDims[3], logicalDims[4], ubChunkRows, ubChunkCols);
229	            return;
230	        }
231	    }
232	
233	    TputChunkedSingle<GlobalDstData, GlobalSrcData, TileData, atomicType, false>(
234	        dstGlobalData, srcGlobalData, stagingTileData, logicalDims[0], logicalDims[1], logicalDims[2], logicalDims[3],
235	        logicalDims[4], ubChunkRows, ubChunkCols);
236	}
237	
238	// ============================================================================
239	// TPUT_IMPL: Remote write operation implementation
240	//
241	// Data flow: srcGlobalData (local GM) → stagingTileData (UB) → dstGlobalData (remote GM)
242	//   - atomicType: Atomic operation type (AtomicNone or AtomicAdd)
243	//
244	// When the GlobalTensor exceeds the UB tile capacity in rows and/or columns,
245	// the transfer is automatically chunked via 2D sliding:
246	//   - Outer dimensions (DIM_0, DIM_1, DIM_2) are iterated explicitly.
247	//   - DIM_3 (rows) is split into tileValidRow-sized chunks.
248	//   - DIM_4 (cols) is split into tileValidCol-sized chunks.
249	//
250	// Constraints for chunked mode:
251	//   - If TileData has static ValidRow, shape3 must be divisible by ValidRow.
252	//     Use DYNAMIC ValidRow for partial row chunk support.
253	//   - If TileData has static ValidCol, shape4 must be divisible by ValidCol.
254	//     Use DYNAMIC ValidCol for partial column chunk support.
255	// ============================================================================
256	
257	template <
258	    typename GlobalDstData, typename GlobalSrcData, typename TileData, AtomicType atomicType = AtomicType::AtomicNone>
259	PTO_INTERNAL void TPUT_IMPL(GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& stagingTileData)
260	{
261	    using T = typename GlobalSrcData::RawDType;
262	
263	    static_assert(std::is_same_v<typename GlobalDstData::RawDType, T>, "TPUT: src/dst element type mismatch");
264	    static_assert(
265	        std::is_same_v<T, typename TileData::DType>, "TPUT: TileData element type must match GlobalData element type");
266	    constexpr bool sameLayout = (GlobalSrcData::layout == GlobalDstData::layout);
267	    static_assert(sameLayout, "TPUT: src/dst layout mismatch");
268	
269	    const int logicalDims[5] = {
270	        static_cast<int>(srcGlobalData.GetShape(GlobalTensorDim::DIM_0)),
271	        static_cast<int>(srcGlobalData.GetShape(GlobalTensorDim::DIM_1)),
272	        static_cast<int>(srcGlobalData.GetShape(GlobalTensorDim::DIM_2)),
273	        static_cast<int>(srcGlobalData.GetShape(GlobalTensorDim::DIM_3)),
274	        static_cast<int>(srcGlobalData.GetShape(GlobalTensorDim::DIM_4))};
275	
276	    const int64_t totalLogicalRows =
277	        static_cast<int64_t>(logicalDims[0]) * logicalDims[1] * logicalDims[2] * logicalDims[3];
278	    const int ubChunkRows = stagingTileData.GetValidRow();
279	    const int ubChunkCols = stagingTileData.GetValidCol();
280	
281	    PTO_ASSERT(ubChunkRows > 0, "TPUT: tileValidRow must be greater than 0");
282	    PTO_ASSERT(ubChunkCols > 0, "TPUT: tileValidCol must be greater than 0");
283	
284	    if (totalLogicalRows == 0 || logicalDims[4] == 0) {
285	        return;
286	    }
287	
288	    if (totalLogicalRows <= ubChunkRows && logicalDims[4] <= ubChunkCols) {
289	        TLOAD(stagingTileData, srcGlobalData);
290	        set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
291	        wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
292	        TSTORE_IMPL<TileData, GlobalDstData, atomicType>(dstGlobalData, stagingTileData);
293	        set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
294	        wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
295	        return;
296	    }
297	
298	    TputChunkedDispatch<GlobalDstData, GlobalSrcData, TileData, atomicType>(
299	        dstGlobalData, srcGlobalData, stagingTileData, logicalDims, ubChunkRows, ubChunkCols);
300	}
301	
302	// Process one chunk in the ping-pong pipeline: overlap TSTORE of previous chunk with TLOAD of current chunk
303	template <typename GlobalDstData, typename GlobalSrcData, typename TileData, AtomicType atomicType, typename StrideT>
304	PTO_INTERNAL void TputPingPongProcessChunk(
305	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& pingTile, TileData& pongTile,
306	    TputPingPongState& pp, int64_t srcOff, int64_t dstOff, int curRows, int curCols, const StrideT& srcChunkStride,
307	    const StrideT& dstChunkStride)
308	{
309	    using T = typename GlobalSrcData::RawDType;
310	    constexpr bool isDynamicRow = (TileData::ValidRow == DYNAMIC);
311	    constexpr bool isDynamicCol = (TileData::ValidCol == DYNAMIC);
312	    using DynShape = Shape<1, 1, 1, DYNAMIC, DYNAMIC>;
313	    using SrcViewT = GlobalTensor<T, DynShape, StrideT, GlobalSrcData::layout>;
314	    using DstViewT = GlobalTensor<T, DynShape, StrideT, GlobalDstData::layout>;
315	
316	    TileData& loadTile = pp.usePing ? pingTile : pongTile;
317	    event_t curEvent = pp.usePing ? EVENT_ID0 : EVENT_ID1;
318	    if constexpr (isDynamicRow)
319	        loadTile.RowMaskInternal = curRows;
320	    if constexpr (isDynamicCol)
321	        loadTile.ColMaskInternal = curCols;
322	
323	    DynShape chunkShape(1, 1, 1, curRows, curCols);
324	    SrcViewT srcView(srcGlobalData.data() + srcOff, chunkShape, srcChunkStride);
325	
326	    if (pp.hasPending) {
327	        TileData& storeTile = pp.usePing ? pongTile : pingTile;
328	        event_t prevEvent = pp.usePing ? EVENT_ID1 : EVENT_ID0;
329	        wait_flag(PIPE_MTE2, PIPE_MTE3, prevEvent);
330	        pipe_barrier(PIPE_ALL);
331	        DynShape pendShape(1, 1, 1, pp.pendingRows, pp.pendingCols);
332	        DstViewT pendView(dstGlobalData.data() + pp.pendingDstOffset, pendShape, dstChunkStride);
333	        TSTORE_IMPL<TileData, DstViewT, atomicType>(pendView, storeTile);
334	        TLOAD(loadTile, srcView);
335	        set_flag(PIPE_MTE3, PIPE_MTE2, prevEvent);
336	        set_flag(PIPE_MTE2, PIPE_MTE3, curEvent);
337	        wait_flag(PIPE_MTE3, PIPE_MTE2, prevEvent);
338	    } else {
339	        TLOAD(loadTile, srcView);
340	        set_flag(PIPE_MTE2, PIPE_MTE3, curEvent);
341	    }
342	
343	    pp.pendingDstOffset = dstOff;
344	    pp.pendingRows = curRows;
345	    pp.pendingCols = curCols;
346	    pp.hasPending = true;
347	    pp.usePing = !pp.usePing;
348	}
349	
350	// Flush the last pending TSTORE in the ping-pong pipeline
351	template <typename GlobalDstData, typename TileData, AtomicType atomicType, typename StrideT>
352	PTO_INTERNAL void TputPingPongFlush(
353	    GlobalDstData& dstGlobalData, TileData& pingTile, TileData& pongTile, TputPingPongState& pp,
354	    const StrideT& dstChunkStride)
355	{
356	    if (!pp.hasPending)
357	        return;
358	
359	    using T = typename GlobalDstData::RawDType;
360	    using DynShape = Shape<1, 1, 1, DYNAMIC, DYNAMIC>;
361	    using DstViewT = GlobalTensor<T, DynShape, StrideT, GlobalDstData::layout>;
362	
363	    TileData& lastTile = pp.usePing ? pongTile : pingTile;
364	    event_t lastEvent = pp.usePing ? EVENT_ID1 : EVENT_ID0;
365	    wait_flag(PIPE_MTE2, PIPE_MTE3, lastEvent);
366	    pipe_barrier(PIPE_ALL);
367	    DynShape lastShape(1, 1, 1, pp.pendingRows, pp.pendingCols);
368	    DstViewT lastView(dstGlobalData.data() + pp.pendingDstOffset, lastShape, dstChunkStride);
369	    TSTORE_IMPL<TileData, DstViewT, atomicType>(lastView, lastTile);
370	    set_flag(PIPE_MTE3, PIPE_MTE2, lastEvent);
371	    wait_flag(PIPE_MTE3, PIPE_MTE2, lastEvent);
372	}
373	
374	// 2D sliding chunked transfer with ping-pong double buffering
375	template <typename GlobalDstData, typename GlobalSrcData, typename TileData, AtomicType atomicType>
376	PTO_INTERNAL void TputChunkedPingPong(
377	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& pingTile, TileData& pongTile, int gShape0,
378	    int gShape1, int gShape2, int gShape3, int gShape4, int tileValidRow, int tileValidCol)
379	{
380	    const int srcStride[5] = {
381	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_0)),
382	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_1)),
383	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_2)),
384	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_3)),
385	        static_cast<int>(srcGlobalData.GetStride(GlobalTensorDim::DIM_4))};
386	    const int dstStride[5] = {
387	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_0)),
388	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_1)),
389	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_2)),
390	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_3)),
391	        static_cast<int>(dstGlobalData.GetStride(GlobalTensorDim::DIM_4))};
392	
393	    using DynStride = Stride<DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC>;
394	    DynStride srcChunkStride(srcStride[0], srcStride[1], srcStride[2], srcStride[3], srcStride[4]);
395	    DynStride dstChunkStride(dstStride[0], dstStride[1], dstStride[2], dstStride[3], dstStride[4]);
396	
397	    TputPingPongState pp;
398	
399	    for (int i0 = 0; i0 < gShape0; ++i0) {
400	        for (int i1 = 0; i1 < gShape1; ++i1) {
401	            for (int i2 = 0; i2 < gShape2; ++i2) {
402	                int64_t srcBase = static_cast<int64_t>(i0) * srcStride[0] + static_cast<int64_t>(i1) * srcStride[1] +
403	                                  static_cast<int64_t>(i2) * srcStride[2];
404	                int64_t dstBase = static_cast<int64_t>(i0) * dstStride[0] + static_cast<int64_t>(i1) * dstStride[1] +
405	                                  static_cast<int64_t>(i2) * dstStride[2];
406	                for (int rowOff = 0; rowOff < gShape3; rowOff += tileValidRow) {
407	                    int curRows = (rowOff + tileValidRow <= gShape3) ? tileValidRow : (gShape3 - rowOff);
408	                    for (int colOff = 0; colOff < gShape4; colOff += tileValidCol) {
409	                        int curCols = (colOff + tileValidCol <= gShape4) ? tileValidCol : (gShape4 - colOff);
410	                        int64_t srcOff = srcBase + static_cast<int64_t>(rowOff) * srcStride[3] +
411	                                         static_cast<int64_t>(colOff) * srcStride[4];
412	                        int64_t dstOff = dstBase + static_cast<int64_t>(rowOff) * dstStride[3] +
413	                                         static_cast<int64_t>(colOff) * dstStride[4];
414	                        TputPingPongProcessChunk<GlobalDstData, GlobalSrcData, TileData, atomicType>(
415	                            dstGlobalData, srcGlobalData, pingTile, pongTile, pp, srcOff, dstOff, curRows, curCols,
416	                            srcChunkStride, dstChunkStride);
417	                    }
418	                }
419	            }
420	        }
421	    }
422	
423	    TputPingPongFlush<GlobalDstData, TileData, atomicType>(dstGlobalData, pingTile, pongTile, pp, dstChunkStride);
424	}
425	
426	// ============================================================================
427	// TPUT_IMPL (ping-pong): Remote write with double buffering
428	// ============================================================================
429	
430	template <
431	    typename GlobalDstData, typename GlobalSrcData, typename TileData, AtomicType atomicType = AtomicType::AtomicNone>
432	PTO_INTERNAL void TPUT_IMPL(
433	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& pingTile, TileData& pongTile)
434	{
435	    using T = typename GlobalSrcData::RawDType;
436	
437	    static_assert(std::is_same_v<T, typename GlobalDstData::RawDType>, "TPUT: src/dst element type mismatch");
438	    static_assert(GlobalSrcData::layout == GlobalDstData::layout, "TPUT: src/dst layout mismatch");
439	    static_assert(
440	        std::is_same_v<T, typename TileData::DType>, "TPUT: TileData element type must match GlobalData element type");
441	
442	    const int gShape0 = srcGlobalData.GetShape(GlobalTensorDim::DIM_0);
443	    const int gShape1 = srcGlobalData.GetShape(GlobalTensorDim::DIM_1);
444	    const int gShape2 = srcGlobalData.GetShape(GlobalTensorDim::DIM_2);
445	    const int gShape3 = srcGlobalData.GetShape(GlobalTensorDim::DIM_3);
446	    const int gShape4 = srcGlobalData.GetShape(GlobalTensorDim::DIM_4);
447	
448	    const int64_t totalRows = static_cast<int64_t>(gShape0) * gShape1 * gShape2 * gShape3;
449	    const int tileValidRow = pingTile.GetValidRow();
450	    const int tileValidCol = pingTile.GetValidCol();
451	
452	    PTO_ASSERT(tileValidRow > 0, "TPUT: tileValidRow must be greater than 0");
453	    PTO_ASSERT(tileValidCol > 0, "TPUT: tileValidCol must be greater than 0");
454	
455	    if (totalRows == 0 || gShape4 == 0) {
456	        return;
457	    }
458	
459	    if (totalRows <= tileValidRow && gShape4 <= tileValidCol) {
460	        TputTransferOnce<TileData, GlobalDstData, GlobalSrcData, atomicType>(dstGlobalData, srcGlobalData, pingTile);
461	        return;
462	    }
463	
464	    constexpr bool isDynamicRow = (TileData::ValidRow == DYNAMIC);
465	    constexpr bool isDynamicCol = (TileData::ValidCol == DYNAMIC);
466	
467	    if constexpr (!isDynamicRow) {
468	        PTO_ASSERT(
469	            gShape3 % tileValidRow == 0,
470	            "TPUT chunked: shape3 must be divisible by tile ValidRow when ValidRow is static. "
471	            "Use a Tile with DYNAMIC ValidRow for partial row chunk support.");
472	    }
473	    if constexpr (!isDynamicCol) {
474	        PTO_ASSERT(
475	            gShape4 % tileValidCol == 0,
476	            "TPUT chunked: shape4 must be divisible by tile ValidCol when ValidCol is static. "
477	            "Use a Tile with DYNAMIC ValidCol for partial column chunk support.");
478	    }
479	
480	    TputChunkedPingPong<GlobalDstData, GlobalSrcData, TileData, atomicType>(
481	        dstGlobalData, srcGlobalData, pingTile, pongTile, gShape0, gShape1, gShape2, gShape3, gShape4, tileValidRow,
482	        tileValidCol);
483	}
484	
485	} // namespace comm
486	} // namespace pto
487	
488	#endif // PTO_COMM_TPUT_HPP
