21	// ============================================================================
22	// TTEST_IMPL: Non-blocking test if signal(s) meet comparison condition
23	//
24	// Returns true if condition is satisfied, false otherwise.
25	// Signal type must be int32_t.
26	// Supports full 5-D signal tensors. Returns true only if ALL signals satisfy.
27	// ============================================================================
28	
29	namespace detail {
30	
31	// Helper: Compare signal value with runtime comparison operator
32	PTO_INTERNAL bool TestCompareSignal(int32_t sigVal, int32_t cmpVal, WaitCmp cmp)
33	{
34	    switch (cmp) {
35	        case WaitCmp::EQ:
36	            return sigVal == cmpVal;
37	        case WaitCmp::NE:
38	            return sigVal != cmpVal;
39	        case WaitCmp::GT:
40	            return sigVal > cmpVal;
41	        case WaitCmp::GE:
42	            return sigVal >= cmpVal;
43	        case WaitCmp::LT:
44	            return sigVal < cmpVal;
45	        case WaitCmp::LE:
46	            return sigVal <= cmpVal;
47	        default:
48	            return false;
49	    }
50	}
51	
52	} // namespace detail
53	
54	template <typename GlobalSignalData>
55	PTO_INTERNAL bool TTEST_IMPL(GlobalSignalData& signalData, int32_t cmpValue, WaitCmp cmp)
56	{
57	    static_assert(std::is_same_v<typename GlobalSignalData::RawDType, int32_t>, "TTEST: signal type must be int32_t");
58	
59	    // Get full 5-D shape and stride
60	    const int s0 = signalData.GetShape(GlobalTensorDim::DIM_0);
61	    const int s1 = signalData.GetShape(GlobalTensorDim::DIM_1);
62	    const int s2 = signalData.GetShape(GlobalTensorDim::DIM_2);
63	    const int s3 = signalData.GetShape(GlobalTensorDim::DIM_3);
64	    const int s4 = signalData.GetShape(GlobalTensorDim::DIM_4);
65	
66	    const int64_t st0 = signalData.GetStride(GlobalTensorDim::DIM_0);
67	    const int64_t st1 = signalData.GetStride(GlobalTensorDim::DIM_1);
68	    const int64_t st2 = signalData.GetStride(GlobalTensorDim::DIM_2);
69	    const int64_t st3 = signalData.GetStride(GlobalTensorDim::DIM_3);
70	    const int64_t st4 = signalData.GetStride(GlobalTensorDim::DIM_4);
71	
72	    volatile __gm__ int32_t* basePtr = (volatile __gm__ int32_t*)signalData.data();
73	
74	    // Test if all signals satisfy the condition (full 5-D traversal)
75	    for (int d0 = 0; d0 < s0; ++d0) {
76	        for (int d1 = 0; d1 < s1; ++d1) {
77	            for (int d2 = 0; d2 < s2; ++d2) {
78	                for (int d3 = 0; d3 < s3; ++d3) {
79	                    for (int d4 = 0; d4 < s4; ++d4) {
80	                        const int64_t idx = d0 * st0 + d1 * st1 + d2 * st2 + d3 * st3 + d4 * st4;
81	                        __asm__ __volatile__("");
82	                        dcci((__gm__ void*)(basePtr + idx), cache_line_t::SINGLE_CACHE_LINE);
83	                        __asm__ __volatile__("");
84	                        if (!detail::TestCompareSignal(basePtr[idx], cmpValue, cmp)) {
85	                            return false;
86	                        }
87	                    }
88	                }
89	            }
90	        }
91	    }
92	    return true;
93	}
