101	    using StrideDyn = pto::Stride<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
102	    using Global = pto::GlobalTensor<T, ShapeDyn, StrideDyn, pto::Layout::ND>;
103	    using TileData = pto::Tile<pto::TileType::Vec, T, 1, kTileElems, pto::BLayout::RowMajor, -1, -1>;
104	
105	    TileData tile(1, kTileElems);
106	    TASSIGN(tile, 0x0);
107	    for (int offset = 0; offset < elemCount; offset += static_cast<int>(kTileElems)) {
108	        int remainElems = elemCount - offset;
109	        int currentElems = (remainElems < static_cast<int>(kTileElems)) ? remainElems : static_cast<int>(kTileElems);
110	        tile.ColMaskInternal = currentElems;
111	        ShapeDyn shape(1, 1, 1, 1, currentElems);
112	        StrideDyn stride(currentElems, currentElems, currentElems, currentElems, 1);
113	        Global srcG(src + offset, shape, stride);
114	        Global dstG(dst + offset, shape, stride);
115	        TLOAD(tile, srcG);
116	        set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
117	        wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
118	        TSTORE(dstG, tile);
119	        set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
120	        wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
121	    }
122	}
