403	template <typename T>
404	bool RunSingleBandwidthCase(
405	    BenchInstr instr, TestContext& ctx, T* outputBuf, uint64_t* profileBufDev, uint64_t* profileBufHost, T* shmem,
406	    uint8_t* outputHost, size_t elemCount, int nRanks, int rootRank, int peerRank, uint8_t* sdmaWorkspace)
407	{
408	    const size_t bytes = elemCount * sizeof(T);
409	    const int warmupIters = SelectWarmupIters(bytes);
410	    const int timedIters = SelectTimedIters(bytes);
411	
412	    if (!CheckAclCall(aclrtMemset(outputBuf, bytes, 0, bytes), "aclrtMemset(outputBuf)")) {
413	        return false;
414	    }
415	
416	    for (int i = 0; i < warmupIters; ++i) {
417	        if (!LaunchBandwidthKernel(
418	                instr, ctx, shmem, nRanks, rootRank, peerRank, static_cast<int>(elemCount), sdmaWorkspace)) {
419	            return false;
420	        }
421	    }
422	
423	    if (!CheckAclCall(aclrtMemset(outputBuf, bytes, 0, bytes), "aclrtMemset(outputBuf)")) {
424	        return false;
425	    }
426	
427	    HcclHostBarrier(ctx.comm, ctx.stream);
428	    const double beginMs = NowMs();
429	    for (int i = 0; i < timedIters; ++i) {
430	        if (!LaunchBandwidthKernel(
431	                instr, ctx, shmem, nRanks, rootRank, peerRank, static_cast<int>(elemCount), sdmaWorkspace)) {
432	            return false;
433	        }
434	    }
435	    const double endMs = NowMs();
436	    HcclHostBarrier(ctx.comm, ctx.stream);
437	
438	    if (!LaunchCopyReceivedBufferKernel(ctx, outputBuf, shmem, rootRank, static_cast<int>(elemCount))) {
439	        return false;
440	    }
441	
442	    const double elapsedMs = endMs - beginMs;
443	    if (ctx.hostCtx.rankId == rootRank) {
444	        if (!CheckAclCall(
445	                aclrtMemcpy(outputHost, bytes, outputBuf, bytes, ACL_MEMCPY_DEVICE_TO_HOST),
446	                "aclrtMemcpy(outputBuf -> host)")) {
447	            return false;
448	        }
449	        if (!VerifyRootBuffer(reinterpret_cast<T*>(outputHost), elemCount, peerRank)) {
450	            return false;
451	        }
452	    }
453	
454	    const double hostAvgUs = elapsedMs * 1000.0 / static_cast<double>(timedIters);
455	    const double hostBandwidthGBps = CalcBandwidthGBps(bytes, timedIters, elapsedMs);
456	
457	    if (!CheckAclCall(aclrtMemset(outputBuf, bytes, 0, bytes), "aclrtMemset(outputBuf)")) {
458	        return false;
459	    }
460	    if (!CheckAclCall(
461	            aclrtMemset(profileBufDev, sizeof(uint64_t), 0, sizeof(uint64_t)), "aclrtMemset(profileBufDev)")) {
462	        return false;
463	    }
464	    HcclHostBarrier(ctx.comm, ctx.stream);
465	    if (!LaunchProfileKernel(
466	            instr, ctx, outputBuf, profileBufDev, shmem, nRanks, rootRank, peerRank, static_cast<int>(elemCount),
467	            warmupIters, timedIters, sdmaWorkspace)) {
468	        return false;
469	    }
470	    HcclHostBarrier(ctx.comm, ctx.stream);
471	
472	    if (ctx.hostCtx.rankId == rootRank) {
473	        if (!CheckAclCall(
474	                aclrtMemcpy(outputHost, bytes, outputBuf, bytes, ACL_MEMCPY_DEVICE_TO_HOST),
475	                "aclrtMemcpy(profile outputBuf -> host)")) {
476	            return false;
477	        }
478	        if (!VerifyRootBuffer(reinterpret_cast<T*>(outputHost), elemCount, peerRank)) {
479	            return false;
480	        }
481	        if (!CheckAclCall(
482	                aclrtMemcpy(
483	                    profileBufHost, sizeof(uint64_t), profileBufDev, sizeof(uint64_t), ACL_MEMCPY_DEVICE_TO_HOST),
484	                "aclrtMemcpy(profileBufDev -> host)")) {
485	            return false;
486	        }
487	
488	        const uint64_t totalCycles = profileBufHost[0];
489	        const double avgCycles = static_cast<double>(totalCycles) / static_cast<double>(timedIters);
490	
491	        std::cout << std::fixed << std::setprecision(2) << "[BW] instr=" << BenchInstrName(instr) << " bytes=" << bytes
492	                  << " iters=" << timedIters << " host_avg_us=" << hostAvgUs
493	                  << " host_bandwidth_GBps=" << hostBandwidthGBps << " device_avg_cycles=" << avgCycles
494	                  << " device_total_cycles=" << totalCycles << std::endl;
495	    }
496	    return true;
497	}
