499	template <typename T>
500	bool RunTGetBandwidthSweepKernel(
501	    int rankId, int nRanks, int nDevices, int firstRankId, int firstDeviceId, const HcclRootInfo* rootInfo)
502	{
503	    const int rootRank = firstRankId;
504	    if (nRanks < 2) {
505	        if (rankId == rootRank) {
506	            std::cout << "[DEBUG] TGET bandwidth test requires at least 2 ranks" << std::endl;
507	        }
508	        return true;
509	    }
510	
511	    TestContext ctx;
512	    if (!ctx.Init(rankId, nRanks, nDevices, firstDeviceId, rootInfo)) {
513	        return false;
514	    }
515	
516	    const int peerRank = (rootRank + 1) % nRanks;
517	    const size_t maxBytes = kMaxBenchBytes;
518	    const size_t maxElems = maxBytes / sizeof(T);
519	
520	    uint8_t* inputHost = nullptr;
521	    uint8_t* outputHost = nullptr;
522	    T* inputBuf = nullptr;
523	    T* outputBuf = nullptr;
524	    uint64_t* profileBufDev = nullptr;
525	    uint64_t* profileBufHost = nullptr;
526	    T* shmem = nullptr;
527	    SdmaWorkspaceManager sdmaMgr;
528	    bool ok = false;
529	
530	    do {
531	        if (!CheckAclCall(aclrtMallocHost(reinterpret_cast<void**>(&inputHost), maxBytes), "aclrtMallocHost(input)")) {
532	            break;
533	        }
534	        if (!CheckAclCall(
535	                aclrtMallocHost(reinterpret_cast<void**>(&outputHost), maxBytes), "aclrtMallocHost(output)")) {
536	            break;
537	        }
538	        if (!CheckAclCall(
539	                aclrtMalloc(reinterpret_cast<void**>(&inputBuf), maxBytes, ACL_MEM_MALLOC_HUGE_FIRST),
540	                "aclrtMalloc(inputBuf)")) {
541	            break;
542	        }
543	        if (!CheckAclCall(
544	                aclrtMalloc(reinterpret_cast<void**>(&outputBuf), maxBytes, ACL_MEM_MALLOC_HUGE_FIRST),
545	                "aclrtMalloc(outputBuf)")) {
546	            break;
547	        }
548	        if (!CheckAclCall(
549	                aclrtMalloc(reinterpret_cast<void**>(&profileBufDev), sizeof(uint64_t), ACL_MEM_MALLOC_HUGE_FIRST),
550	                "aclrtMalloc(profileBufDev)")) {
551	            break;
552	        }
553	        if (!CheckAclCall(
554	                aclrtMallocHost(reinterpret_cast<void**>(&profileBufHost), sizeof(uint64_t)),
555	                "aclrtMallocHost(profileBufHost)")) {
556	            break;
557	        }
558	
559	        T* inputHostData = reinterpret_cast<T*>(inputHost);
560	        T* outputHostData = reinterpret_cast<T*>(outputHost);
561	        for (size_t i = 0; i < maxElems; ++i) {
562	            inputHostData[i] = static_cast<T>(i + rankId * 10000);
563	            outputHostData[i] = static_cast<T>(-1);
564	        }
565	
566	        if (!CheckAclCall(
567	                aclrtMemcpy(inputBuf, maxBytes, inputHostData, maxBytes, ACL_MEMCPY_HOST_TO_DEVICE),
568	                "aclrtMemcpy(input -> inputBuf)")) {
569	            break;
570	        }
571	
572	        uint64_t localWinBase = ctx.hostCtx.windowsIn[rankId];
573	        size_t winOffset = 0;
574	        shmem = reinterpret_cast<T*>(WindowAlloc(localWinBase, winOffset, 64 * sizeof(int32_t) + 2 * maxBytes));
575	
576	        HcclHostBarrier(ctx.comm, ctx.stream);
577	        if (!LaunchPrepareKernel(ctx, inputBuf, shmem, static_cast<int>(maxElems))) {
578	            break;
579	        }
580	        HcclHostBarrier(ctx.comm, ctx.stream);
581	
582	        if (rankId == rootRank && !sdmaMgr.Init()) {
583	            std::cerr << "[ERROR] SdmaWorkspaceManager Init failed!" << std::endl;
584	            break;
585	        }
586	
587	        if (rankId == rootRank) {
588	            std::cout << "\n================ TGET/TGET_ASYNC Bandwidth Sweep ================" << std::endl;
589	            std::cout << "peer_rank=" << peerRank << " dtype=float tile_elems=" << kTileElems << std::endl;
590	        }
591	
592	        bool sweepOk = true;
593	        for (size_t bytes : kBenchBytes) {
594	            const size_t elemCount = bytes / sizeof(T);
595	            if (!RunSingleBandwidthCase(
596	                    BenchInstr::TGet, ctx, outputBuf, profileBufDev, profileBufHost, shmem, outputHost, elemCount,
597	                    nRanks, rootRank, peerRank, nullptr)) {
598	                sweepOk = false;
599	                break;
600	            }
601	            if (!RunSingleBandwidthCase(
602	                    BenchInstr::TGetAsync, ctx, outputBuf, profileBufDev, profileBufHost, shmem, outputHost, elemCount,
603	                    nRanks, rootRank, peerRank,
604	                    rankId == rootRank ? reinterpret_cast<uint8_t*>(sdmaMgr.GetWorkspaceAddr()) : nullptr)) {
605	                sweepOk = false;
606	                break;
607	            }
608	            if (rankId == rootRank) {
609	                std::cout << std::endl;
610	            }
611	        }
612	        ok = sweepOk;
613	    } while (false);
614	
615	    if (inputHost != nullptr) {
616	        ctx.aclStatus |= aclrtFreeHost(inputHost);
617	    }
618	    if (outputHost != nullptr) {
619	        ctx.aclStatus |= aclrtFreeHost(outputHost);
620	    }
621	    if (inputBuf != nullptr) {
622	        ctx.aclStatus |= aclrtFree(inputBuf);
623	    }
624	    if (outputBuf != nullptr) {
625	        ctx.aclStatus |= aclrtFree(outputBuf);
626	    }
627	    if (profileBufDev != nullptr) {
628	        ctx.aclStatus |= aclrtFree(profileBufDev);
629	    }
630	    if (profileBufHost != nullptr) {
631	        ctx.aclStatus |= aclrtFreeHost(profileBufHost);
632	    }
633	    if (rankId == rootRank) {
634	        sdmaMgr.Finalize();
635	    }
636	
637	    return ctx.Finalize() && ok;
638	}
639	
640	bool RunTGetBandwidthSweep(int n_ranks, int n_devices, int first_rank_id, int first_device_id)
641	{
642	    return ForkAndRunWithHcclRootInfo(
643	        n_ranks, first_rank_id, first_device_id, [&](int rankId, const HcclRootInfo* rootInfo) {
644	            return RunTGetBandwidthSweepKernel<float>(
645	                rankId, n_ranks, n_devices, first_rank_id, first_device_id, rootInfo);
646	        });
647	}
