649	struct TGetDeviceBaselinePolicy {
650	    static constexpr bool kIsTGet = true;
651	
652	    static int SourceRank(int, int peerRank) { return peerRank; }
653	
654	    template <typename T>
655	    static bool Reset(
656	        int rankId, int rootRank, int, const DeviceBaselineConfig& config, DeviceBaselineResources<T>& resources)
657	    {
658	        bool resetOk = true;
659	        if (rankId == rootRank) {
660	            resetOk = CheckAclCall(
661	                          aclrtMemset(resources.recvShmem, config.totalBytes, 0xFF, config.totalBytes),
662	                          "aclrtMemset(device baseline dst)") &&
663	                      CheckAclCall(
664	                          aclrtMemset(resources.profileBufDev, 2 * sizeof(uint64_t), 0, 2 * sizeof(uint64_t)),
665	                          "aclrtMemset(device baseline profile)");
666	        }
667	        char launchStatus = resetOk ? 1 : 0;
668	        CommMpiBcast(&launchStatus, 1, COMM_MPI_CHAR, rootRank);
669	        return launchStatus != 0;
670	    }
671	
672	    template <typename T>
673	    static bool Complete(
674	        int rankId, int rootRank, int peerRank, int patternOuter, bool measured, int outer,
675	        const DeviceBaselineConfig& config, DeviceBaselineResources<T>& resources, uint64_t& outerCycles)
676	    {
677	        bool verifyOk = true;
678	        if (rankId == rootRank) {
679	            verifyOk = CheckAclCall(
680	                           aclrtMemcpy(
681	                               resources.verifyHost, config.totalBytes, resources.recvShmem, config.totalBytes,
682	                               ACL_MEMCPY_DEVICE_TO_HOST),
683	                           "aclrtMemcpy(device baseline verify)") &&
684	                       CheckAclCall(
685	                           aclrtMemcpy(
686	                               resources.profileBufHost, 2 * sizeof(uint64_t), resources.profileBufDev,
687	                               2 * sizeof(uint64_t), ACL_MEMCPY_DEVICE_TO_HOST),
688	                           "aclrtMemcpy(device baseline profile)");
689	            verifyOk = verifyOk && resources.profileBufHost[1] == 1;
690	            outerCycles = resources.profileBufHost[0];
691	            verifyOk = verifyOk && benchmark::VerifyDeviceBaselinePattern(
692	                                       resources.verifyHost, peerRank, patternOuter, measured, outer, config.postCount,
693	                                       config.elemCount);
694	        }
695	        char verifyStatus = verifyOk ? 1 : 0;
696	        CommMpiBcast(&verifyStatus, 1, COMM_MPI_CHAR, rootRank);
697	        return verifyStatus != 0;
698	    }
699	};
