21	// ============================================================================
22	// 1D Vector Tile Test Kernel
23	// TGET: Remote read operation - each rank reads data from next rank
24	// ============================================================================
25	template <typename T, size_t count>
26	__global__ AICORE void TGetKernelImpl(
27	    __gm__ T* dst, __gm__ T* src, __gm__ T* shmem, int nranks, __gm__ CommDeviceContext* hcclCtx, int phase)
28	{
29	    if (nranks <= 0)
30	        return;
31	    using ShapeDyn = pto::Shape<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
32	    using StrideDyn = pto::Stride<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
33	    using Global = pto::GlobalTensor<T, ShapeDyn, StrideDyn, pto::Layout::ND>;
34	
35	    // UB Tile definition: 1D Vector Tile
36	    using TileData = pto::Tile<pto::TileType::Vec, T, 1, count, pto::BLayout::RowMajor, -1, -1>;
37	
38	    ShapeDyn shape(1, 1, 1, 1, count);
39	    StrideDyn stride(count, count, count, count, 1);
40	
41	    int my_rank = static_cast<int>(hcclCtx->rankId);
42	    int next_rank = (my_rank + 1) % nranks;
43	
44	    __gm__ uint8_t* shmem_bytes = reinterpret_cast<__gm__ uint8_t*>(shmem);
45	    __gm__ T* shmem_data = reinterpret_cast<__gm__ T*>(shmem_bytes + 64 * sizeof(int32_t));
46	    __gm__ T* send_shmem = (__gm__ T*)((__gm__ T*)shmem_data + 0);
47	    __gm__ T* recv_shmem = (__gm__ T*)((__gm__ T*)shmem_data + count);
48	
49	    if (phase == 0) {
50	        Global srcG(src, shape, stride);
51	        Global sendG(send_shmem, shape, stride);
52	
53	        TileData stagingTile(1, count);
54	        TASSIGN(stagingTile, 0x0);
55	
56	        TLOAD(stagingTile, srcG);
57	        set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
58	        wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
59	        TSTORE(sendG, stagingTile);
60	        set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
61	        wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
62	
63	        pipe_barrier(PIPE_ALL);
64	    } else {
65	        Global dstG(dst, shape, stride);
66	        Global recvG(recv_shmem, shape, stride);
67	
68	        TileData stagingTile(1, count);
69	        TileData resultTile(1, count);
70	        TASSIGN(stagingTile, 0x0);
71	        TASSIGN(resultTile, 0x10000);
72	
73	        __gm__ T* remote_send_shmem = CommRemotePtr(hcclCtx, send_shmem, next_rank);
74	        Global remoteSendG(remote_send_shmem, shape, stride);
75	
76	        pto::comm::TGET(recvG, remoteSendG, stagingTile);
77	
78	        pipe_barrier(PIPE_ALL);
79	
80	        TLOAD(resultTile, recvG);
81	        set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
82	        wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
83	        TSTORE(dstG, resultTile);
84	        set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
85	        wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
86	    }
87	}
88	
89	template <typename T, size_t count>
90	bool RunGetRingKernel(int rank_id, int n_ranks, int n_devices, int first_device_id, const HcclRootInfo* rootInfo)
91	{
92	    if (n_ranks <= 0)
93	        return false;
94	    TestContext ctx;
95	    if (!ctx.Init(rank_id, n_ranks, n_devices, first_device_id, rootInfo))
96	        return false;
97	
98	    void* input_ptr = nullptr;
99	    void* output_ptr = nullptr;
100	    if (aclrtMalloc(&input_ptr, count * sizeof(T), ACL_MEM_MALLOC_HUGE_FIRST) != 0 ||
101	        aclrtMalloc(&output_ptr, count * sizeof(T), ACL_MEM_MALLOC_HUGE_FIRST) != 0) {
102	        std::cerr << "[ERROR] aclrtMalloc failed!" << std::endl;
103	        return false;
104	    }
105	
106	    uint8_t* input_host = nullptr;
107	    uint8_t* output_host = nullptr;
108	    if (aclrtMallocHost(reinterpret_cast<void**>(&input_host), count * sizeof(T)) != 0 ||
109	        aclrtMallocHost(reinterpret_cast<void**>(&output_host), count * sizeof(T)) != 0) {
110	        std::cerr << "[ERROR] aclrtMallocHost failed!" << std::endl;
111	        return false;
112	    }
113	
114	    // Initialize Input/Output Host
115	    for (size_t i = 0; i < count; ++i) {
116	        reinterpret_cast<T*>(input_host)[i] = static_cast<T>(i + rank_id * 10000);
117	        reinterpret_cast<T*>(output_host)[i] = static_cast<T>(-1);
118	    }
119	
120	    aclrtMemcpy(input_ptr, count * sizeof(T), input_host, count * sizeof(T), ACL_MEMCPY_HOST_TO_DEVICE);
121	
122	    // Allocate window memory for shared buffer (sync buffer + data buffer)
123	    uint64_t localWinBase = ctx.hostCtx.windowsIn[rank_id];
124	    size_t winOffset = 0;
125	    void* shmem_ptr = WindowAlloc(localWinBase, winOffset, 64 * sizeof(int32_t) + 4 * count * sizeof(T));
126	
127	    // Barrier to ensure all ranks have initialized
128	    HcclHostBarrier(ctx.comm, ctx.stream);
129	
130	    // Phase 0: populate local send buffer
131	    TGetKernelImpl<T, count>
132	        <<<1, nullptr, ctx.stream>>>((T*)output_ptr, (T*)input_ptr, (T*)shmem_ptr, n_ranks, ctx.deviceCtx, 0);
133	    aclrtSynchronizeStream(ctx.stream);
134	
135	    HcclHostBarrier(ctx.comm, ctx.stream);
136	
137	    // Phase 1: TGET from remote + read to dst
138	    TGetKernelImpl<T, count>
139	        <<<1, nullptr, ctx.stream>>>((T*)output_ptr, (T*)input_ptr, (T*)shmem_ptr, n_ranks, ctx.deviceCtx, 1);
140	    ctx.aclStatus = aclrtSynchronizeStream(ctx.stream);
141	
142	    aclrtMemcpy(output_host, count * sizeof(T), output_ptr, count * sizeof(T), ACL_MEMCPY_DEVICE_TO_HOST);
143	
144	    // Verify: Each rank should get data from next rank
145	    // rank_id reads from (rank_id + 1) % n_ranks, which has data: i + next_rank * 10000
146	    bool is_ok = true;
147	    if (n_ranks < 2) {
148	        std::cout << "[DEBUG] I can't run this test with less than 2 ranks" << std::endl;
149	        return false;
150	    }
151	    int next_rank = (rank_id + 1) % n_ranks;
152	    for (int i = 0; i < count; ++i) {
153	        T value = reinterpret_cast<T*>(output_host)[i];
154	        T expected = static_cast<T>(i + next_rank * 10000);
155	        if (value != expected) {
156	            std::cout << "Rank " << rank_id << " Device " << ctx.deviceId << " Status " << ctx.aclStatus << std::endl;
157	            std::cout << "Expected value: " << (float)expected << std::endl;
158	            std::cout << "Actual value: " << (float)value << std::endl;
159	            is_ok = false;
160	            break;
161	        }
162	    }
163	
164	#if ENABLE_DEBUG_PRINT
165	    if (is_ok && rank_id == 0) {
166	        std::cout << "\n================================================================" << std::endl;
167	        std::cout << "[DEBUG] Rank 0: TGET Ring SUCCESSFUL!" << std::endl;
168	        std::cout << "Sample Result (First 5 elements): [ ";
169	        for (size_t i = 0; i < (count > 5 ? 5 : count); ++i) {
170	            std::cout << (float)reinterpret_cast<T*>(output_host)[i] << " ";
171	        }
172	        if (count > 5)
173	            std::cout << "... ";
174	        std::cout << "]" << std::endl;
175	        std::cout << "================================================================\n" << std::endl;
176	    }
177	#endif
178	
179	    ctx.aclStatus |= aclrtFreeHost(input_host);
180	    ctx.aclStatus |= aclrtFreeHost(output_host);
181	    ctx.aclStatus |= aclrtFree(input_ptr);
182	    ctx.aclStatus |= aclrtFree(output_ptr);
183	
184	    return ctx.Finalize() && is_ok;
