201	// ============================================================================
202	// 2D Tile Test Kernel
203	// Tests TGET with 2D Vec Tile (rows x cols) stored in UB
204	// ============================================================================
205	template <typename T, size_t rows, size_t cols>
206	__global__ AICORE void TGetKernel2DImpl(
207	    __gm__ T* dst, __gm__ T* src, __gm__ T* shmem, int nranks, __gm__ CommDeviceContext* hcclCtx, int phase)
208	{
209	    if (nranks <= 0)
210	        return;
211	    constexpr size_t total_count = rows * cols;
212	
213	    using ShapeDyn = pto::Shape<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
214	    using StrideDyn = pto::Stride<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
215	    using Global = pto::GlobalTensor<T, ShapeDyn, StrideDyn, pto::Layout::ND>;
216	
217	    // UB Tile definition: 2D Vec Tile (rows x cols) stored in Unified Buffer
218	    using TileData = pto::Tile<pto::TileType::Vec, T, rows, cols, pto::BLayout::RowMajor, -1, -1>;
219	
220	    // 2D GlobalTensor shape: [1, 1, 1, rows, cols]
221	    ShapeDyn shape(1, 1, 1, rows, cols);
222	    StrideDyn stride(total_count, total_count, total_count, cols, 1);
223	
224	    int my_rank = static_cast<int>(hcclCtx->rankId);
225	    int next_rank = (my_rank + 1) % nranks;
226	
227	    __gm__ uint8_t* shmem_bytes = reinterpret_cast<__gm__ uint8_t*>(shmem);
228	    __gm__ T* shmem_data = reinterpret_cast<__gm__ T*>(shmem_bytes + 64 * sizeof(int32_t));
229	    __gm__ T* send_shmem = (__gm__ T*)((__gm__ T*)shmem_data + 0);
230	    __gm__ T* recv_shmem = (__gm__ T*)((__gm__ T*)shmem_data + total_count);
231	
232	    if (phase == 0) {
233	        Global srcG(src, shape, stride);
234	        Global sendG(send_shmem, shape, stride);
235	
236	        TileData stagingTile(rows, cols);
237	        TASSIGN(stagingTile, 0x0);
238	
239	        TLOAD(stagingTile, srcG);
240	        set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
241	        wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
242	        TSTORE(sendG, stagingTile);
243	        set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
244	        wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
245	
246	        pipe_barrier(PIPE_ALL);
247	    } else {
248	        Global dstG(dst, shape, stride);
249	        Global recvG(recv_shmem, shape, stride);
250	
251	        TileData stagingTile(rows, cols);
252	        TileData resultTile(rows, cols);
253	        TASSIGN(stagingTile, 0x0);
254	        TASSIGN(resultTile, 0x10000);
255	
256	        __gm__ T* remote_send_shmem = CommRemotePtr(hcclCtx, send_shmem, next_rank);
257	        Global remoteSendG(remote_send_shmem, shape, stride);
258	
259	        pto::comm::TGET(recvG, remoteSendG, stagingTile);
260	
261	        pipe_barrier(PIPE_ALL);
262	
263	        TLOAD(resultTile, recvG);
264	        set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
265	        wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
266	        TSTORE(dstG, resultTile);
267	        set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
268	        wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
269	    }
270	}
