272	template <typename T, size_t rows, size_t cols>
273	bool RunGetRing2DKernel(int rank_id, int n_ranks, int n_devices, int first_device_id, const HcclRootInfo* rootInfo)
274	{
275	    if (n_ranks <= 0)
276	        return false;
277	    constexpr size_t total_count = rows * cols;
278	
279	    TestContext ctx;
280	    if (!ctx.Init(rank_id, n_ranks, n_devices, first_device_id, rootInfo))
281	        return false;
282	
283	    void* input_ptr = nullptr;
284	    void* output_ptr = nullptr;
285	    if (aclrtMalloc(&input_ptr, total_count * sizeof(T), ACL_MEM_MALLOC_HUGE_FIRST) != 0 ||
286	        aclrtMalloc(&output_ptr, total_count * sizeof(T), ACL_MEM_MALLOC_HUGE_FIRST) != 0) {
287	        std::cerr << "[ERROR] aclrtMalloc failed!" << std::endl;
288	        return false;
289	    }
290	
291	    uint8_t* input_host = nullptr;
292	    uint8_t* output_host = nullptr;
293	    if (aclrtMallocHost(reinterpret_cast<void**>(&input_host), total_count * sizeof(T)) != 0 ||
294	        aclrtMallocHost(reinterpret_cast<void**>(&output_host), total_count * sizeof(T)) != 0) {
295	        std::cerr << "[ERROR] aclrtMallocHost failed!" << std::endl;
296	        return false;
297	    }
298	
299	    // Initialize Input/Output Host - 2D data in row-major order
300	    for (size_t r = 0; r < rows; ++r) {
301	        for (size_t c = 0; c < cols; ++c) {
302	            size_t idx = r * cols + c;
303	            reinterpret_cast<T*>(input_host)[idx] = static_cast<T>(idx + rank_id * 10000);
304	            reinterpret_cast<T*>(output_host)[idx] = static_cast<T>(-1);
305	        }
306	    }
307	
308	    aclrtMemcpy(input_ptr, total_count * sizeof(T), input_host, total_count * sizeof(T), ACL_MEMCPY_HOST_TO_DEVICE);
309	
310	    // Allocate window memory for shared buffer (sync buffer + data buffer)
311	    uint64_t localWinBase = ctx.hostCtx.windowsIn[rank_id];
312	    size_t winOffset = 0;
313	    void* shmem_ptr = WindowAlloc(localWinBase, winOffset, 64 * sizeof(int32_t) + 4 * total_count * sizeof(T));
314	
315	    // Barrier to ensure all ranks have initialized
316	    HcclHostBarrier(ctx.comm, ctx.stream);
317	
318	    // Phase 0: populate local send buffer
319	    TGetKernel2DImpl<T, rows, cols>
320	        <<<1, nullptr, ctx.stream>>>((T*)output_ptr, (T*)input_ptr, (T*)shmem_ptr, n_ranks, ctx.deviceCtx, 0);
321	    aclrtSynchronizeStream(ctx.stream);
322	
323	    HcclHostBarrier(ctx.comm, ctx.stream);
324	
325	    // Phase 1: TGET from remote + read to dst
326	    TGetKernel2DImpl<T, rows, cols>
327	        <<<1, nullptr, ctx.stream>>>((T*)output_ptr, (T*)input_ptr, (T*)shmem_ptr, n_ranks, ctx.deviceCtx, 1);
328	    ctx.aclStatus = aclrtSynchronizeStream(ctx.stream);
329	
330	    aclrtMemcpy(output_host, total_count * sizeof(T), output_ptr, total_count * sizeof(T), ACL_MEMCPY_DEVICE_TO_HOST);
331	
332	    // Verify: Each rank should get data from next rank
333	    bool is_ok = true;
334	    if (n_ranks < 2) {
335	        std::cout << "[DEBUG] I can't run this test with less than 2 ranks" << std::endl;
336	        return false;
337	    }
338	    int next_rank = (rank_id + 1) % n_ranks;
339	    for (size_t r = 0; r < rows && is_ok; ++r) {
340	        for (size_t c = 0; c < cols && is_ok; ++c) {
341	            size_t idx = r * cols + c;
342	            T value = reinterpret_cast<T*>(output_host)[idx];
343	            T expected = static_cast<T>(idx + next_rank * 10000);
344	            if (value != expected) {
345	                std::cout << "Rank " << rank_id << " Device " << ctx.deviceId << " Status " << ctx.aclStatus
346	                          << std::endl;
347	                std::cout << "At [" << r << ", " << c << "] (idx=" << idx << "):" << std::endl;
348	                std::cout << "Expected value: " << (float)expected << std::endl;
349	                std::cout << "Actual value: " << (float)value << std::endl;
350	                is_ok = false;
351	            }
352	        }
353	    }
354	
355	#if ENABLE_DEBUG_PRINT
356	    if (is_ok && rank_id == 0) {
357	        std::cout << "\n================================================================" << std::endl;
358	        std::cout << "[DEBUG] Rank 0: TGET 2D Ring SUCCESSFUL! (" << rows << "x" << cols << ")" << std::endl;
359	        std::cout << "Sample Result (First row): [ ";
360	        for (size_t c = 0; c < (cols > 5 ? 5 : cols); ++c) {
361	            std::cout << (float)reinterpret_cast<T*>(output_host)[c] << " ";
362	        }
363	        if (cols > 5)
364	            std::cout << "... ";
365	        std::cout << "]" << std::endl;
366	        std::cout << "================================================================\n" << std::endl;
367	    }
368	#endif
369	
370	    ctx.aclStatus |= aclrtFreeHost(input_host);
371	    ctx.aclStatus |= aclrtFreeHost(output_host);
372	    ctx.aclStatus |= aclrtFree(input_ptr);
373	    ctx.aclStatus |= aclrtFree(output_ptr);
374	
375	    return ctx.Finalize() && is_ok;
376	}
