392	// ============================================================================
393	// Large Shape Chunked Test Kernel
394	// Tests TGET with GlobalTensor shape > UB tile capacity (forces chunked path)
395	// GlobalTensor: (1, 1, 1, total_rows, cols), Tile: (tile_rows, cols)
396	// where total_rows > tile_rows, triggering automatic chunking in TGET_IMPL
397	// ============================================================================
398	template <typename T, size_t total_rows, size_t cols, size_t tile_rows>
399	__global__ AICORE void TGetLargeShapeKernelImpl(
400	    __gm__ T* dst, __gm__ T* src, __gm__ T* shmem, int nranks, __gm__ CommDeviceContext* hcclCtx, int phase)
401	{
402	    if (nranks <= 0)
403	        return;
404	    constexpr size_t total_count = total_rows * cols;
405	    static_assert(total_rows > tile_rows, "total_rows must exceed tile_rows to test chunking");
406	    static_assert(total_rows % tile_rows == 0, "total_rows must be divisible by tile_rows for static tile");
407	
408	    using ShapeDyn = pto::Shape<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
409	    using StrideDyn = pto::Stride<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
410	    using Global = pto::GlobalTensor<T, ShapeDyn, StrideDyn, pto::Layout::ND>;
411	    using TileData = pto::Tile<pto::TileType::Vec, T, tile_rows, cols, pto::BLayout::RowMajor, -1, -1>;
412	
413	    // Full shape for the large GlobalTensor
414	    ShapeDyn fullShape(1, 1, 1, total_rows, cols);
415	    StrideDyn fullStride(total_count, total_count, total_count, cols, 1);
416	
417	    // Chunk shape for manual TLOAD/TSTORE of setup/readback
418	    constexpr size_t chunk_count = tile_rows * cols;
419	    ShapeDyn chunkShape(1, 1, 1, tile_rows, cols);
420	    StrideDyn chunkStride(chunk_count, chunk_count, chunk_count, cols, 1);
421	
422	    int my_rank = static_cast<int>(hcclCtx->rankId);
423	    int next_rank = (my_rank + 1) % nranks;
424	
425	    __gm__ uint8_t* shmem_bytes = reinterpret_cast<__gm__ uint8_t*>(shmem);
426	    __gm__ T* shmem_data = reinterpret_cast<__gm__ T*>(shmem_bytes + 64 * sizeof(int32_t));
427	    __gm__ T* send_shmem = shmem_data;
428	    __gm__ T* recv_shmem = shmem_data + total_count;
429	
430	    if (phase == 0) {
431	        TileData stagingTile(tile_rows, cols);
432	        TASSIGN(stagingTile, 0x0);
433	
434	        for (size_t off = 0; off < total_count; off += chunk_count) {
435	            Global srcChunk(src + off, chunkShape, chunkStride);
436	            Global sendChunk(send_shmem + off, chunkShape, chunkStride);
437	            TLOAD(stagingTile, srcChunk);
438	            set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
439	            wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
440	            TSTORE(sendChunk, stagingTile);
441	            set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
442	            wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
443	        }
444	
445	        pipe_barrier(PIPE_ALL);
446	    } else {
447	        Global sendG(send_shmem, fullShape, fullStride);
448	        Global recvG(recv_shmem, fullShape, fullStride);
449	
450	        TileData stagingTile(tile_rows, cols);
451	        TileData resultTile(tile_rows, cols);
452	        TASSIGN(stagingTile, 0x0);
453	        TASSIGN(resultTile, 0x10000);
454	
455	        __gm__ T* remote_send_shmem = CommRemotePtr(hcclCtx, send_shmem, next_rank);
456	        Global remoteSendG(remote_send_shmem, fullShape, fullStride);
457	        pto::comm::TGET(recvG, remoteSendG, stagingTile);
458	
459	        pipe_barrier(PIPE_ALL);
460	
461	        for (size_t off = 0; off < total_count; off += chunk_count) {
462	            Global recvChunk(recv_shmem + off, chunkShape, chunkStride);
463	            Global dstChunk(dst + off, chunkShape, chunkStride);
464	            TLOAD(resultTile, recvChunk);
465	            set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
466	            wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
467	            TSTORE(dstChunk, resultTile);
468	            set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
469	            wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
470	        }
471	    }
472	}
