611	template <typename T, size_t d0, size_t d1, size_t d2, size_t d3, size_t cols, size_t tile_rows>
612	__global__ AICORE void TGetMultiDimKernelImpl(
613	    __gm__ T* dst, __gm__ T* src, __gm__ T* shmem, int nranks, __gm__ CommDeviceContext* hcclCtx, int phase)
614	{
615	    if (nranks <= 0)
616	        return;
617	    constexpr size_t total_count = d0 * d1 * d2 * d3 * cols;
618	    static_assert(d0 * d1 * d2 * d3 > tile_rows, "total rows must exceed tile_rows to test chunking");
619	    static_assert(d3 % tile_rows == 0, "d3 must be divisible by tile_rows for static tile");
620	
621	    using ShapeDyn = pto::Shape<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
622	    using StrideDyn = pto::Stride<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
623	    using Global = pto::GlobalTensor<T, ShapeDyn, StrideDyn, pto::Layout::ND>;
624	    using TileData = pto::Tile<pto::TileType::Vec, T, tile_rows, cols, pto::BLayout::RowMajor, -1, -1>;
625	
626	    // ND strides for contiguous row-major
627	    constexpr size_t s4 = 1;
628	    constexpr size_t s3 = cols;
629	    constexpr size_t s2 = d3 * cols;
630	    constexpr size_t s1 = d2 * d3 * cols;
631	    constexpr size_t s0 = d1 * d2 * d3 * cols;
632	
633	    ShapeDyn fullShape(d0, d1, d2, d3, cols);
634	    StrideDyn fullStride(s0, s1, s2, s3, s4);
635	
636	    // Chunk shape for manual TLOAD/TSTORE of setup/readback
637	    constexpr size_t chunk_count = tile_rows * cols;
638	    ShapeDyn chunkShape(1, 1, 1, tile_rows, cols);
639	    StrideDyn chunkStride(chunk_count, chunk_count, chunk_count, cols, 1);
640	
641	    int my_rank = static_cast<int>(hcclCtx->rankId);
642	    int next_rank = (my_rank + 1) % nranks;
643	
644	    __gm__ uint8_t* shmem_bytes = reinterpret_cast<__gm__ uint8_t*>(shmem);
645	    __gm__ T* shmem_data = reinterpret_cast<__gm__ T*>(shmem_bytes + 64 * sizeof(int32_t));
646	    __gm__ T* send_shmem = shmem_data;
647	    __gm__ T* recv_shmem = shmem_data + total_count;
648	
649	    if (phase == 0) {
650	        TileData stagingTile(tile_rows, cols);
651	        TASSIGN(stagingTile, 0x0);
652	
653	        for (size_t off = 0; off < total_count; off += chunk_count) {
654	            Global srcChunk(src + off, chunkShape, chunkStride);
655	            Global sendChunk(send_shmem + off, chunkShape, chunkStride);
656	            TLOAD(stagingTile, srcChunk);
657	            set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
658	            wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
659	            TSTORE(sendChunk, stagingTile);
660	            set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
661	            wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
662	        }
663	
664	        pipe_barrier(PIPE_ALL);
665	    } else {
666	        Global sendG(send_shmem, fullShape, fullStride);
667	        Global recvG(recv_shmem, fullShape, fullStride);
668	
669	        TileData stagingTile(tile_rows, cols);
670	        TileData resultTile(tile_rows, cols);
671	        TASSIGN(stagingTile, 0x0);
672	        TASSIGN(resultTile, 0x10000);
673	
674	        __gm__ T* remote_send_shmem = CommRemotePtr(hcclCtx, send_shmem, next_rank);
675	        Global remoteSendG(remote_send_shmem, fullShape, fullStride);
676	        pto::comm::TGET(recvG, remoteSendG, stagingTile);
677	
678	        pipe_barrier(PIPE_ALL);
679	
680	        for (size_t off = 0; off < total_count; off += chunk_count) {
681	            Global recvChunk(recv_shmem + off, chunkShape, chunkStride);
682	            Global dstChunk(dst + off, chunkShape, chunkStride);
683	            TLOAD(resultTile, recvChunk);
684	            set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
685	            wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
686	            TSTORE(dstChunk, resultTile);
687	            set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
688	            wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
689	        }
690	    }
691	}
