693	template <typename T, size_t d0, size_t d1, size_t d2, size_t d3, size_t cols, size_t tile_rows>
694	bool RunGetRingMultiDimKernel(
695	    int rank_id, int n_ranks, int n_devices, int first_device_id, const HcclRootInfo* rootInfo)
696	{
697	    if (n_ranks <= 0)
698	        return false;
699	    constexpr size_t total_count = d0 * d1 * d2 * d3 * cols;
700	
701	    TestContext ctx;
702	    if (!ctx.Init(rank_id, n_ranks, n_devices, first_device_id, rootInfo))
703	        return false;
704	
705	    void* input_ptr = nullptr;
706	    void* output_ptr = nullptr;
707	    if (aclrtMalloc(&input_ptr, total_count * sizeof(T), ACL_MEM_MALLOC_HUGE_FIRST) != 0 ||
708	        aclrtMalloc(&output_ptr, total_count * sizeof(T), ACL_MEM_MALLOC_HUGE_FIRST) != 0) {
709	        std::cerr << "[ERROR] aclrtMalloc failed!" << std::endl;
710	        return false;
711	    }
712	
713	    uint8_t* input_host = nullptr;
714	    uint8_t* output_host = nullptr;
715	    if (aclrtMallocHost(reinterpret_cast<void**>(&input_host), total_count * sizeof(T)) != 0 ||
716	        aclrtMallocHost(reinterpret_cast<void**>(&output_host), total_count * sizeof(T)) != 0) {
717	        std::cerr << "[ERROR] aclrtMallocHost failed!" << std::endl;
718	        return false;
719	    }
720	
721	    for (size_t i = 0; i < total_count; ++i) {
722	        reinterpret_cast<T*>(input_host)[i] = static_cast<T>(i + rank_id * 10000);
723	        reinterpret_cast<T*>(output_host)[i] = static_cast<T>(-1);
724	    }
725	
726	    aclrtMemcpy(input_ptr, total_count * sizeof(T), input_host, total_count * sizeof(T), ACL_MEMCPY_HOST_TO_DEVICE);
727	
728	    uint64_t localWinBase = ctx.hostCtx.windowsIn[rank_id];
729	    size_t winOffset = 0;
730	    void* shmem_ptr = WindowAlloc(localWinBase, winOffset, 64 * sizeof(int32_t) + 4 * total_count * sizeof(T));
731	
732	    HcclHostBarrier(ctx.comm, ctx.stream);
733	
734	    // Phase 0: populate local send buffer
735	    TGetMultiDimKernelImpl<T, d0, d1, d2, d3, cols, tile_rows>
736	        <<<1, nullptr, ctx.stream>>>((T*)output_ptr, (T*)input_ptr, (T*)shmem_ptr, n_ranks, ctx.deviceCtx, 0);
737	    aclrtSynchronizeStream(ctx.stream);
738	
739	    HcclHostBarrier(ctx.comm, ctx.stream);
740	
741	    // Phase 1: TGET from remote + read to dst
742	    TGetMultiDimKernelImpl<T, d0, d1, d2, d3, cols, tile_rows>
743	        <<<1, nullptr, ctx.stream>>>((T*)output_ptr, (T*)input_ptr, (T*)shmem_ptr, n_ranks, ctx.deviceCtx, 1);
744	    ctx.aclStatus = aclrtSynchronizeStream(ctx.stream);
745	
746	    aclrtMemcpy(output_host, total_count * sizeof(T), output_ptr, total_count * sizeof(T), ACL_MEMCPY_DEVICE_TO_HOST);
747	
748	    bool is_ok = true;
749	    if (n_ranks < 2) {
750	        std::cout << "[DEBUG] I can't run this test with less than 2 ranks" << std::endl;
751	        return false;
752	    }
753	    int next_rank = (rank_id + 1) % n_ranks;
754	    for (size_t i = 0; i < total_count && is_ok; ++i) {
755	        T value = reinterpret_cast<T*>(output_host)[i];
756	        T expected = static_cast<T>(i + next_rank * 10000);
757	        if (value != expected) {
758	            std::cout << "Rank " << rank_id << " Device " << ctx.deviceId << " Status " << ctx.aclStatus << std::endl;
759	            std::cout << "At index " << i << ":" << std::endl;
760	            std::cout << "Expected value: " << (float)expected << std::endl;
761	            std::cout << "Actual value: " << (float)value << std::endl;
762	            is_ok = false;
763	        }
764	    }
765	
766	#if ENABLE_DEBUG_PRINT
767	    if (is_ok && rank_id == 0) {
768	        std::cout << "\n================================================================" << std::endl;
769	        std::cout << "[DEBUG] Rank 0: TGET MultiDim SUCCESSFUL! (" << d0 << "x" << d1 << "x" << d2 << "x" << d3 << "x"
770	                  << cols << ", tile=" << tile_rows << "x" << cols << ")" << std::endl;
771	        std::cout << "Sample Result (First 5 elements): [ ";
772	        for (size_t i = 0; i < (total_count > 5 ? 5 : total_count); ++i) {
773	            std::cout << (float)reinterpret_cast<T*>(output_host)[i] << " ";
774	        }
775	        if (total_count > 5)
776	            std::cout << "... ";
777	        std::cout << "]" << std::endl;
778	        std::cout << "================================================================\n" << std::endl;
779	    }
780	#endif
781	
782	    ctx.aclStatus |= aclrtFreeHost(input_host);
783	    ctx.aclStatus |= aclrtFreeHost(output_host);
784	    ctx.aclStatus |= aclrtFree(input_ptr);
785	    ctx.aclStatus |= aclrtFree(output_ptr);
786	
787	    return ctx.Finalize() && is_ok;
788	}
