809	// Irregular Shape Chunked Test Kernel
810	// Tests TGET with GlobalTensor where total_rows is NOT divisible by tile_rows.
811	// This exercises the partial last-chunk path in TGET_IMPL (DYNAMIC ValidRow).
812	// The setup/readback loops also handle partial last chunks explicitly.
813	// ============================================================================
814	template <typename T, size_t total_rows, size_t cols, size_t tile_rows>
815	__global__ AICORE void TGetIrregularShapeKernelImpl(
816	    __gm__ T* dst, __gm__ T* src, __gm__ T* shmem, int nranks, __gm__ CommDeviceContext* hcclCtx, int phase)
817	{
818	    if (nranks <= 0)
819	        return;
820	    constexpr size_t total_count = total_rows * cols;
821	    static_assert(total_rows > tile_rows, "total_rows must exceed tile_rows to test chunking");
822	    // Note: total_rows % tile_rows may NOT be 0 — this is intentional for testing partial chunks!
823	
824	    using ShapeDyn = pto::Shape<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
825	    using StrideDyn = pto::Stride<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
826	    using Global = pto::GlobalTensor<T, ShapeDyn, StrideDyn, pto::Layout::ND>;
827	    // Tile with DYNAMIC ValidRow (-1) to support partial last chunks
828	    using TileData = pto::Tile<pto::TileType::Vec, T, tile_rows, cols, pto::BLayout::RowMajor, -1, -1>;
829	
830	    // Full shape for the large GlobalTensor
831	    ShapeDyn fullShape(1, 1, 1, total_rows, cols);
832	    StrideDyn fullStride(total_count, total_count, total_count, cols, 1);
833	
834	    int my_rank = static_cast<int>(hcclCtx->rankId);
835	    int next_rank = (my_rank + 1) % nranks;
836	
837	    __gm__ uint8_t* shmem_bytes = reinterpret_cast<__gm__ uint8_t*>(shmem);
838	    __gm__ T* shmem_data = reinterpret_cast<__gm__ T*>(shmem_bytes + 64 * sizeof(int32_t));
839	    __gm__ T* send_shmem = shmem_data;
840	    __gm__ T* recv_shmem = shmem_data + total_count;
841	
842	    if (phase == 0) {
843	        TileData stagingTile(tile_rows, cols);
844	        TASSIGN(stagingTile, 0x0);
845	
846	        for (size_t rowOff = 0; rowOff < total_rows; rowOff += tile_rows) {
847	            size_t currentRows = (rowOff + tile_rows <= total_rows) ? tile_rows : (total_rows - rowOff);
848	            size_t off = rowOff * cols;
849	
850	            stagingTile.RowMaskInternal = currentRows;
851	
852	            ShapeDyn chunkShape(1, 1, 1, currentRows, cols);
853	            StrideDyn chunkStride(currentRows * cols, currentRows * cols, currentRows * cols, cols, 1);
854	
855	            Global srcChunk(src + off, chunkShape, chunkStride);
856	            Global sendChunk(send_shmem + off, chunkShape, chunkStride);
857	            TLOAD(stagingTile, srcChunk);
858	            set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
859	            wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
860	            TSTORE(sendChunk, stagingTile);
861	            set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
862	            wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
863	        }
864	
865	        pipe_barrier(PIPE_ALL);
866	    } else {
867	        Global sendG(send_shmem, fullShape, fullStride);
868	        Global recvG(recv_shmem, fullShape, fullStride);
869	
870	        TileData stagingTile(tile_rows, cols);
871	        TileData resultTile(tile_rows, cols);
872	        TASSIGN(stagingTile, 0x0);
873	        TASSIGN(resultTile, 0x10000);
874	
875	        // stagingTile starts with tile_rows RowMask — TGET_IMPL reads initial tileValidRow
876	        __gm__ T* remote_send_shmem = CommRemotePtr(hcclCtx, send_shmem, next_rank);
877	        Global remoteSendG(remote_send_shmem, fullShape, fullStride);
878	        pto::comm::TGET(recvG, remoteSendG, stagingTile);
879	
880	        pipe_barrier(PIPE_ALL);
881	
882	        for (size_t rowOff = 0; rowOff < total_rows; rowOff += tile_rows) {
883	            size_t currentRows = (rowOff + tile_rows <= total_rows) ? tile_rows : (total_rows - rowOff);
884	            size_t off = rowOff * cols;
885	
886	            resultTile.RowMaskInternal = currentRows;
887	
888	            ShapeDyn chunkShape(1, 1, 1, currentRows, cols);
889	            StrideDyn chunkStride(currentRows * cols, currentRows * cols, currentRows * cols, cols, 1);
890	
891	            Global recvChunk(recv_shmem + off, chunkShape, chunkStride);
892	            Global dstChunk(dst + off, chunkShape, chunkStride);
893	            TLOAD(resultTile, recvChunk);
894	            set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
895	            wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
896	            TSTORE(dstChunk, resultTile);
897	            set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
898	            wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
899	        }
900	    }
901	}
