1029	// ============================================================================
1030	// 2D Sliding Test Kernel
1031	// Tests TGET with GlobalTensor where BOTH rows and cols exceed the UB tile.
1032	// The Tile uses DYNAMIC ValidRow (-1) and DYNAMIC ValidCol (-1) to support
1033	// partial last chunks in both dimensions.
1034	//   GlobalTensor: (1, 1, 1, total_rows, total_cols)
1035	//   Tile physical dims: (tile_rows, tile_cols)
1036	//   TGET_IMPL automatically does 2D sliding over (total_rows × total_cols).
1037	// ============================================================================
1038	template <typename T, size_t total_rows, size_t total_cols, size_t tile_rows, size_t tile_cols>
1039	__global__ AICORE void TGet2DSlidingKernelImpl(
1040	    __gm__ T* dst, __gm__ T* src, __gm__ T* shmem, int nranks, __gm__ CommDeviceContext* hcclCtx, int phase)
1041	{
1042	    if (nranks <= 0)
1043	        return;
1044	    constexpr size_t total_count = total_rows * total_cols;
1045	    static_assert(
1046	        total_rows > tile_rows || total_cols > tile_cols,
1047	        "At least one dimension must exceed tile size to test 2D sliding");
1048	
1049	    using ShapeDyn = pto::Shape<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
1050	    using StrideDyn = pto::Stride<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
1051	    using Global = pto::GlobalTensor<T, ShapeDyn, StrideDyn, pto::Layout::ND>;
1052	    // Tile with DYNAMIC ValidRow and DYNAMIC ValidCol for partial chunk support
1053	    using TileData = pto::Tile<pto::TileType::Vec, T, tile_rows, tile_cols, pto::BLayout::RowMajor, -1, -1>;
1054	
1055	    ShapeDyn fullShape(1, 1, 1, total_rows, total_cols);
1056	    StrideDyn fullStride(total_count, total_count, total_count, total_cols, 1);
1057	
1058	    int my_rank = static_cast<int>(hcclCtx->rankId);
1059	    int next_rank = (my_rank + 1) % nranks;
1060	
1061	    __gm__ uint8_t* shmem_bytes = reinterpret_cast<__gm__ uint8_t*>(shmem);
1062	    __gm__ T* shmem_data = reinterpret_cast<__gm__ T*>(shmem_bytes + 64 * sizeof(int32_t));
1063	    __gm__ T* send_shmem = shmem_data;
1064	    __gm__ T* recv_shmem = shmem_data + total_count;
1065	
1066	    if (phase == 0) {
1067	        TileData stagingTile(tile_rows, tile_cols);
1068	        TASSIGN(stagingTile, 0x0);
1069	
1070	        for (size_t rowOff = 0; rowOff < total_rows; rowOff += tile_rows) {
1071	            size_t curRows = (rowOff + tile_rows <= total_rows) ? tile_rows : (total_rows - rowOff);
1072	            stagingTile.RowMaskInternal = curRows;
1073	
1074	            for (size_t colOff = 0; colOff < total_cols; colOff += tile_cols) {
1075	                size_t curCols = (colOff + tile_cols <= total_cols) ? tile_cols : (total_cols - colOff);
1076	                stagingTile.ColMaskInternal = curCols;
1077	
1078	                size_t off = rowOff * total_cols + colOff;
1079	                ShapeDyn chunkShape(1, 1, 1, curRows, curCols);
1080	                StrideDyn chunkStride(total_count, total_count, total_count, total_cols, 1);
1081	
1082	                Global srcChunk(src + off, chunkShape, chunkStride);
1083	                Global sendChunk(send_shmem + off, chunkShape, chunkStride);
1084	                TLOAD(stagingTile, srcChunk);
1085	                set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
1086	                wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
1087	                TSTORE(sendChunk, stagingTile);
1088	                set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
1089	                wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
1090	            }
1091	        }
1092	
1093	        pipe_barrier(PIPE_ALL);
1094	    } else {
1095	        Global sendG(send_shmem, fullShape, fullStride);
1096	        Global recvG(recv_shmem, fullShape, fullStride);
1097	
1098	        TileData stagingTile(tile_rows, tile_cols);
1099	        TileData resultTile(tile_rows, tile_cols);
1100	        TASSIGN(stagingTile, 0x0);
1101	        TASSIGN(resultTile, 0x10000);
1102	
1103	        __gm__ T* remote_send_shmem = CommRemotePtr(hcclCtx, send_shmem, next_rank);
1104	        Global remoteSendG(remote_send_shmem, fullShape, fullStride);
1105	        pto::comm::TGET(recvG, remoteSendG, stagingTile);
1106	
1107	        pipe_barrier(PIPE_ALL);
1108	
1109	        for (size_t rowOff = 0; rowOff < total_rows; rowOff += tile_rows) {
1110	            size_t curRows = (rowOff + tile_rows <= total_rows) ? tile_rows : (total_rows - rowOff);
1111	            resultTile.RowMaskInternal = curRows;
1112	
1113	            for (size_t colOff = 0; colOff < total_cols; colOff += tile_cols) {
1114	                size_t curCols = (colOff + tile_cols <= total_cols) ? tile_cols : (total_cols - colOff);
1115	                resultTile.ColMaskInternal = curCols;
1116	
1117	                size_t off = rowOff * total_cols + colOff;
1118	                ShapeDyn chunkShape(1, 1, 1, curRows, curCols);
1119	                StrideDyn chunkStride(total_count, total_count, total_count, total_cols, 1);
1120	
1121	                Global recvChunk(recv_shmem + off, chunkShape, chunkStride);
1122	                Global dstChunk(dst + off, chunkShape, chunkStride);
1123	                TLOAD(resultTile, recvChunk);
1124	                set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
1125	                wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
1126	                TSTORE(dstChunk, resultTile);
1127	                set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
1128	                wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
1129	            }
1130	        }
1131	    }
1132	}
