1134	template <typename T, size_t total_rows, size_t total_cols, size_t tile_rows, size_t tile_cols>
1135	bool RunGetRing2DSlidingKernel(
1136	    int rank_id, int n_ranks, int n_devices, int first_device_id, const HcclRootInfo* rootInfo)
1137	{
1138	    if (n_ranks <= 0)
1139	        return false;
1140	    constexpr size_t total_count = total_rows * total_cols;
1141	
1142	    TestContext ctx;
1143	    if (!ctx.Init(rank_id, n_ranks, n_devices, first_device_id, rootInfo))
1144	        return false;
1145	
1146	    void* input_ptr = nullptr;
1147	    void* output_ptr = nullptr;
1148	    if (aclrtMalloc(&input_ptr, total_count * sizeof(T), ACL_MEM_MALLOC_HUGE_FIRST) != 0 ||
1149	        aclrtMalloc(&output_ptr, total_count * sizeof(T), ACL_MEM_MALLOC_HUGE_FIRST) != 0) {
1150	        std::cerr << "[ERROR] aclrtMalloc failed!" << std::endl;
1151	        return false;
1152	    }
1153	
1154	    uint8_t* input_host = nullptr;
1155	    uint8_t* output_host = nullptr;
1156	    if (aclrtMallocHost(reinterpret_cast<void**>(&input_host), total_count * sizeof(T)) != 0 ||
1157	        aclrtMallocHost(reinterpret_cast<void**>(&output_host), total_count * sizeof(T)) != 0) {
1158	        std::cerr << "[ERROR] aclrtMallocHost failed!" << std::endl;
1159	        return false;
1160	    }
1161	
1162	    for (size_t i = 0; i < total_count; ++i) {
1163	        reinterpret_cast<T*>(input_host)[i] = static_cast<T>(i + rank_id * 10000);
1164	        reinterpret_cast<T*>(output_host)[i] = static_cast<T>(-1);
1165	    }
1166	
1167	    aclrtMemcpy(input_ptr, total_count * sizeof(T), input_host, total_count * sizeof(T), ACL_MEMCPY_HOST_TO_DEVICE);
1168	
1169	    uint64_t localWinBase = ctx.hostCtx.windowsIn[rank_id];
1170	    size_t winOffset = 0;
1171	    void* shmem_ptr = WindowAlloc(localWinBase, winOffset, 64 * sizeof(int32_t) + 4 * total_count * sizeof(T));
1172	
1173	    HcclHostBarrier(ctx.comm, ctx.stream);
1174	
1175	    // Phase 0: populate local send buffer
1176	    TGet2DSlidingKernelImpl<T, total_rows, total_cols, tile_rows, tile_cols>
1177	        <<<1, nullptr, ctx.stream>>>((T*)output_ptr, (T*)input_ptr, (T*)shmem_ptr, n_ranks, ctx.deviceCtx, 0);
1178	    aclrtSynchronizeStream(ctx.stream);
1179	
1180	    HcclHostBarrier(ctx.comm, ctx.stream);
1181	
1182	    // Phase 1: TGET from remote + read to dst
1183	    TGet2DSlidingKernelImpl<T, total_rows, total_cols, tile_rows, tile_cols>
1184	        <<<1, nullptr, ctx.stream>>>((T*)output_ptr, (T*)input_ptr, (T*)shmem_ptr, n_ranks, ctx.deviceCtx, 1);
1185	    ctx.aclStatus = aclrtSynchronizeStream(ctx.stream);
1186	
1187	    aclrtMemcpy(output_host, total_count * sizeof(T), output_ptr, total_count * sizeof(T), ACL_MEMCPY_DEVICE_TO_HOST);
1188	
1189	    bool is_ok = true;
1190	    if (n_ranks < 2) {
1191	        std::cout << "[DEBUG] I can't run this test with less than 2 ranks" << std::endl;
1192	        return false;
1193	    }
1194	    int next_rank = (rank_id + 1) % n_ranks;
1195	    for (size_t i = 0; i < total_count && is_ok; ++i) {
1196	        T value = reinterpret_cast<T*>(output_host)[i];
1197	        T expected = static_cast<T>(i + next_rank * 10000);
1198	        if (value != expected) {
1199	            size_t row = i / total_cols;
1200	            size_t col = i % total_cols;
1201	            std::cout << "Rank " << rank_id << " Device " << ctx.deviceId << " Status " << ctx.aclStatus << std::endl;
1202	            std::cout << "At [" << row << ", " << col << "] (idx=" << i << "):" << std::endl;
1203	            std::cout << "Expected value: " << (float)expected << std::endl;
1204	            std::cout << "Actual value: " << (float)value << std::endl;
1205	            is_ok = false;
1206	        }
1207	    }
1208	
1209	#if ENABLE_DEBUG_PRINT
1210	    if (is_ok && rank_id == 0) {
1211	        constexpr size_t rowChunks = (total_rows + tile_rows - 1) / tile_rows;
1212	        constexpr size_t colChunks = (total_cols + tile_cols - 1) / tile_cols;
1213	        std::cout << "\n================================================================" << std::endl;
1214	        std::cout << "[DEBUG] Rank 0: TGET 2DSliding SUCCESSFUL! (" << total_rows << "x" << total_cols
1215	                  << ", tile=" << tile_rows << "x" << tile_cols << ", chunks=" << rowChunks << "x" << colChunks << "="
1216	                  << (rowChunks * colChunks) << ")" << std::endl;
1217	        std::cout << "Sample Result (First 5 elements): [ ";
1218	        for (size_t i = 0; i < (total_count > 5 ? 5 : total_count); ++i) {
1219	            std::cout << (float)reinterpret_cast<T*>(output_host)[i] << " ";
1220	        }
1221	        if (total_count > 5)
1222	            std::cout << "... ";
1223	        std::cout << "]" << std::endl;
1224	        std::cout << "Last 5 elements: [ ";
1225	        for (size_t i = (total_count > 5 ? total_count - 5 : 0); i < total_count; ++i) {
1226	            std::cout << (float)reinterpret_cast<T*>(output_host)[i] << " ";
1227	        }
1228	        std::cout << "]" << std::endl;
1229	        std::cout << "================================================================\n" << std::endl;
1230	    }
1231	#endif
1232	
1233	    ctx.aclStatus |= aclrtFreeHost(input_host);
1234	    ctx.aclStatus |= aclrtFreeHost(output_host);
1235	    ctx.aclStatus |= aclrtFree(input_ptr);
1236	    ctx.aclStatus |= aclrtFree(output_ptr);
1237	
1238	    return ctx.Finalize() && is_ok;
1239	}
