1275	// Ping-Pong Double Buffering Test Kernel
1276	// Tests TGET with two staging tiles to overlap TLOAD and TSTORE.
1277	// Uses the 4-parameter TGET(dst, src, pingTile, pongTile) overload.
1278	//   GlobalTensor: (1, 1, 1, total_rows, total_cols)
1279	//   Tile logical chunk: (tile_rows, tile_cols); physical cols padded to 32B for Vec RowMajor
1280	// ============================================================================
1281	template <typename T, size_t total_rows, size_t total_cols, size_t tile_rows, size_t tile_cols>
1282	__global__ AICORE void TGetPingPongKernelImpl(
1283	    __gm__ T* dst, __gm__ T* src, __gm__ T* shmem, int nranks, __gm__ CommDeviceContext* hcclCtx, int phase)
1284	{
1285	    if (nranks <= 0)
1286	        return;
1287	    constexpr size_t total_count = total_rows * total_cols;
1288	    static_assert(
1289	        total_rows > tile_rows || total_cols > tile_cols,
1290	        "At least one dimension must exceed tile size to test ping-pong chunking");
1291	    constexpr size_t tile_cols_phys = ((tile_cols * sizeof(T) + 31) / 32) * (32 / sizeof(T));
1292	    static_assert(tile_cols_phys >= tile_cols, "aligned tile cols must cover logical tile cols");
1293	
1294	    using ShapeDyn = pto::Shape<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
1295	    using StrideDyn = pto::Stride<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
1296	    using Global = pto::GlobalTensor<T, ShapeDyn, StrideDyn, pto::Layout::ND>;
1297	    using TileData = pto::Tile<pto::TileType::Vec, T, tile_rows, tile_cols_phys, pto::BLayout::RowMajor, -1, -1>;
1298	
1299	    ShapeDyn fullShape(1, 1, 1, total_rows, total_cols);
1300	    StrideDyn fullStride(total_count, total_count, total_count, total_cols, 1);
1301	
1302	    int my_rank = static_cast<int>(hcclCtx->rankId);
1303	    int next_rank = (my_rank + 1) % nranks;
1304	
1305	    __gm__ uint8_t* shmem_bytes = reinterpret_cast<__gm__ uint8_t*>(shmem);
1306	    __gm__ T* shmem_data = reinterpret_cast<__gm__ T*>(shmem_bytes + 64 * sizeof(int32_t));
1307	    __gm__ T* send_shmem = shmem_data;
1308	    __gm__ T* recv_shmem = shmem_data + total_count;
1309	
1310	    constexpr size_t tileUBBytes = ((tile_rows * tile_cols_phys * sizeof(T) + 1023) / 1024) * 1024;
1311	
1312	    if (phase == 0) {
1313	        TileData pingTile(tile_rows, tile_cols);
1314	        TASSIGN(pingTile, 0x0);
1315	
1316	        for (size_t rowOff = 0; rowOff < total_rows; rowOff += tile_rows) {
1317	            size_t curRows = (rowOff + tile_rows <= total_rows) ? tile_rows : (total_rows - rowOff);
1318	            pingTile.RowMaskInternal = curRows;
1319	
1320	            for (size_t colOff = 0; colOff < total_cols; colOff += tile_cols) {
1321	                size_t curCols = (colOff + tile_cols <= total_cols) ? tile_cols : (total_cols - colOff);
1322	                pingTile.ColMaskInternal = curCols;
1323	
1324	                size_t off = rowOff * total_cols + colOff;
1325	                ShapeDyn chunkShape(1, 1, 1, curRows, curCols);
1326	                StrideDyn chunkStride(total_count, total_count, total_count, total_cols, 1);
1327	
1328	                Global srcChunk(src + off, chunkShape, chunkStride);
1329	                Global sendChunk(send_shmem + off, chunkShape, chunkStride);
1330	                TLOAD(pingTile, srcChunk);
1331	                set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
1332	                wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
1333	                TSTORE(sendChunk, pingTile);
1334	                set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
1335	                wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
1336	            }
1337	        }
1338	
1339	        pipe_barrier(PIPE_ALL);
1340	    } else {
1341	        Global sendG(send_shmem, fullShape, fullStride);
1342	        Global recvG(recv_shmem, fullShape, fullStride);
1343	
1344	        TileData pingTile(tile_rows, tile_cols);
1345	        TileData pongTile(tile_rows, tile_cols);
1346	        TileData resultTile(tile_rows, tile_cols);
1347	        TASSIGN(pingTile, 0x0);
1348	        TASSIGN(pongTile, tileUBBytes);
1349	        TASSIGN(resultTile, 2 * tileUBBytes);
1350	
1351	        __gm__ T* remote_send_shmem = CommRemotePtr(hcclCtx, send_shmem, next_rank);
1352	        Global remoteSendG(remote_send_shmem, fullShape, fullStride);
1353	        pto::comm::TGET(recvG, remoteSendG, pingTile, pongTile);
1354	
1355	        pipe_barrier(PIPE_ALL);
1356	
1357	        for (size_t rowOff = 0; rowOff < total_rows; rowOff += tile_rows) {
1358	            size_t curRows = (rowOff + tile_rows <= total_rows) ? tile_rows : (total_rows - rowOff);
1359	            resultTile.RowMaskInternal = curRows;
1360	
1361	            for (size_t colOff = 0; colOff < total_cols; colOff += tile_cols) {
1362	                size_t curCols = (colOff + tile_cols <= total_cols) ? tile_cols : (total_cols - colOff);
1363	                resultTile.ColMaskInternal = curCols;
1364	
1365	                size_t off = rowOff * total_cols + colOff;
1366	                ShapeDyn chunkShape(1, 1, 1, curRows, curCols);
1367	                StrideDyn chunkStride(total_count, total_count, total_count, total_cols, 1);
1368	
1369	                Global recvChunk(recv_shmem + off, chunkShape, chunkStride);
1370	                Global dstChunk(dst + off, chunkShape, chunkStride);
1371	                TLOAD(resultTile, recvChunk);
1372	                set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
1373	                wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
1374	                TSTORE(dstChunk, resultTile);
1375	                set_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
1376	                wait_flag(PIPE_MTE3, PIPE_MTE2, EVENT_ID0);
1377	            }
1378	        }
1379	    }
1380	}
